(window.STORIES=window.STORIES||[]).push(...[{"n": 12, "l": "الجزء ١٣ | إبراهيم ٣", "u": "https://www.facebook.com/groups/710210019782034/permalink/725181024951600/", "t": "#قصص_الأنبياء\n#الحلقة_الثالثة_عشرة\n#قصة_إبراهيم(٣)\n#إسماعيل_الذبيح\n#قصة_زمزم\nإبراهيم عليه السلام كان كِبِر في السن ومكنش عنده أولاد، \nوكان بيتمنى إنه يكون عنده ولد، \nفدعا ربنا إنه يرزقه الذرية الصالحة: \n\"رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ * فَبَشَّرْنَاهُ بِغُلَامٍ حَلِيمٍ \" \nوكانت سارة عقيم لا تلد، \nفوهبت سارة لإبراهيم عليه السلام \"هاجر\"، وبقت ملك يمين له، \nوملك اليمين زيها زي الزوجة من ناحية المعاشرة الزوجية والإنجاب، \nفحملت هاجر ... وولدت إسماعيل عليه السلام \nوطبعا كأي أب لسه أول مرة ينجب طفل من صلبه، إبراهيم عليه السلام اتعلق بولده إسماعيل، \nوكمان هنا الوضع مختلف لأن الولد جه لأب كبير في السن يعني بعد طول اشتياق وصبر فأكيد الإهتمام هيكون مُضاعف... \nفهنا غارت سارة \n \nمع إنها هي إللي وهبت هاجر لإبراهيم عليه السلام عشان تخلف له ولد، لكن طبيعة غيرة النساء تغلب\n \nيعني غيرة المرأة من الزوجة التانية دي حاجة طبيعية لا تُحاسب عليها إلا إذا المرأة تعدت بسبب الغيرة وظلمت أختها فاغتابتها أو طلبت من زوجها إنه يطلقها أو كادت لها المكائد، وما إلى ذلك، \n فالغيرة مادامت في القلب ويظهر منها الشيء المعقول اللي ما يتسببش في ضرر أو سوء ومادفعتش المرأة لإرتكاب أي محرم، فالمرأة لا تُحاسب على الغيرة دي\n \nولو بصينا لسارة هنلاقي إن من حقها فعلا تغير في موقف زي ده الصراحة، \nإنتم متخلين زوجة مرت مع زوجها بأحداث كتير وعاشت معاه سنين طويلة -وده مش أي زوج ده إبراهيم خليل الله\n \nفتقوم الزوجة دي تلاقي واحدة تانية في يوم وليلة مفرحة قلب زوجها بالولد إللي هي ما قدرتش توهبه له، ومستحوزة  هي والولد على جزء كبير من اهتمامه\n \nلاشك إن من حقها تغير وقلبها يَضِيق بده، \nفربنا عز وجل رأفةً بسارة ورحمةً بمشاعرها أمر إبراهيم عليه السلام إنه ياخد هاجر وابنها الرضيع إسماعيل ويوديهم مكان تاني ،إللي هو مكة، \nخدوا بالكم إن ربنا لما يريد شيء بيهيء له أسبابه... فسبحان الملك الذي يدبر الأمر كله بحكمته وعلمه الواسع ورحمته وإليه يُرجَعُ الأمر كله\n \n☆حد هيقول يعني تقصدي إيه\nيعني أقصد إن بعدين ربنا هيؤمر إبراهيم وإسماعيل عليهما السلام  إنهم يبنوا الكعبة البيت الحرام، فإزاي كانوا هيبنوها  وهم أصلا قاعدين في فلسطين والبيت الحرام هيكون في مكة\nفكان لازم ربنا يهيأ أسباب سفرهم لمكة أصلا، \nو كمان ساعتها مكة كانت صحراء جرداء ومكنش ينفع لسه حد يعيش هناك ولا كان في زمزم \n لسه ولا كان في أي حاجة..فإزاي بقى كان كل ده هيحصل وييجوا مكة ويحفروا زمزم\n \nفبتقدير وتدبير من ربنا عز وجل، سارة غارت وبالتالي ربنا أمر إبراهيم عليه السلام إنه يأخذ هاجر وإسماعيل لمكة عشان يهيء الأسباب إن البيت الحرام يتبنى وتبقى البلد الحرام مكة بلد معمور يأتي إليها الناس أفواجا من كل مكان فسبحان الله العظيم\n \n◇ومن هنا أحب أقول لكم محدش يزعل لما يدعي دعوة وتتأخر، أو لما تحصلك أي حاجة تضايقك.. \nمحدش يعرف الخير فين لأننا ما عندناش علم الله الوسع المحيط بكل شيء ولا عندنا حكمته الواسعة عشان نقدر  نحكم على الأمور \nمش يمكن ربنا بيهيأ الأسباب عشان يحقق لنا  إللي نفسنا فيه وأحسن كمان؟!! \nمش يمكن ربنا قَدَّر الحاجة إللي احنا شايفينها وحشة ومضايقانا دلوقتي عشان يمنع عننا كارثة في المستقبل؟ \nاعرفوا كويس أوي إن تقدير ربنا لينا داااايما خير، بس احنا نثق فيه ونتوكل عليه وننقاد له\n \nنرجع نكمل كلامنا : \nإبراهيم عليه السلام أخد هاجر وإسماعيل وسافروا لمكة عند موضع البيت الحرام إللي ماكنش لسه اتبنى وكان أرض صحراء جرداء من غير زرع ولا مية، ساب لها قِربة مية وجراب فيه تمر، \n يعني نقدر نقول إزازة مية وكيس تمر، \nوبعدين سابهم وإداهم ضهره ومشي!!، \nفهي استغربت\n...وقعدت تنادي عليه: \nيا إبراهيم إنت سايبنا لمين هنا وماشي؟! \nوهو مش بيبص لها ومش بيرد ومكمل مشي...! \nوهي تنادي عليه وتكرر نفس السؤال...فهي حست إن في حاجة، فسألِته: هو ربنا إللي أمرك بكده؟ \nفالْتَفَت وقال: نعم...فقالت بكل ثقة : إذاً لن يضيعنا\n \nيعني مادام ربنا إللي أمر وقدر كده يبقى أمره وقدره خيييير \n \n☆انتم مخيلين\nزوجة فجأة زوجها يجيبها في صحرا هي وابنها ويسيب معاها بشوية تمر ومية ويمشي ويسيبهم وكمان ما يردش عليها يطمنها بكلمة ولا يشرح لها شيء هو نفسه ما يملكش إنه يتكلم فيه لسه،\n تقوم بدل ما تتهمه إنه مش أب ولا عنده رحمة ولا إنسانية –لإنها عارفة كويس أخلاقه ودينه- تفكر في أول حاجة إييييه؟؟؟  ربنا.. مالك الملك.. مالك إبراهيم ومالكها ومالك إسماعيل.. \nوكإن مفيش أي حاجة تانية هتطمنها لو السؤال ده كانت إجابته لأ..\nمجرد ما اطمنت إن ربنا هو إللي أمر بكده ارتاحت واطمنت\n \nدايما قولها لنفسك كل ما تحصلك مشكلة... \nكل ما تتأخر عنك دعوة... \nكل ما يشتد عليك البلاء... \nقول لنفسك: مش ده قدر ربنا ؟ مش هو إللي أمر بده؟ مش هو إللي هيأ أسباب ده كله وأنا عامل استخارة وواخد بالأسباب زي ما أمرني ومُسلّم له كل أموري؟ \nخلااااااص = يبقى ربنا مش هيضيعني \n \nبس خد بالك بقى\n \n متكونش إنت سبب في إللي بيحصلك ده وترمي بلاك وشكوتك على قدر ربنا \nيعني مايكونش عندك امتحانات مثلا وماذاكرتش فحليت وحش و تيجي تقول يلاّ قدر ربنا كله خير أنا ما شاركتش في السقوط ده\n \nلأ، الكلام ده مش سليم.. لاااازم تاخد بالأسباب وتستخير ربك كمان وده من الأسباب\n... \nلما تاخد بالأسباب وتذاكر ثم متنجحش  كدة ده قدر الله بابتلاء إنت ما اتسببتش فيه، \nيبقى هنا تقول لنفسك قدر ربنا ليا كله خير وأكيد ربنا رايد بحكمته أمر تاني أنا لسه مش فاهمه ولا شايفه، وهكمل أخذ بالأسباب ومش هوقف لإن الأخد بالأسباب ده طاعة لله في حد ذاته، لحد ما ربنا يكشف لي من الحكمة ما يُطمـئِن قلبي أكثر ويقر عيني بالثمرة إن شاء الله. \nبعد ما إبراهيم عليه السلام مشي بعيد عنهم رفع إيده للسماء وقال:\n يارب أنا تركت أهلي في مكان مافيهوش زرع عند بيتك المحرم زي ما أمرتني ورجائي إنك تخلي بعض الناس يروحوا يسكنوا معاهم هناك عشان ما يبقوش لوحدهم كده في المكان المُوحش ده\n \n\"رَبَّنَا إِنِّي أَسْكَنْتُ مِنْ ذُرِّيَّتِي بِوَادٍ غَيْرِ ذِي زَرْعٍ عِنْدَ بَيْتِكَ الْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا الصَّلَاةَ ، \nفَاجْعَلْ أَفْئِدَةً مِنَ النَّاسِ تَهْوِي إِلَيْهِمْ وَارْزُقْهُمْ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ\" \nكانت هاجر بتاكل من التمر وتشرب من المية إللي كانت معاها وترضع إسماعيل، \nلحد ما المية والتمر خلصوا واللبن بتاعها جف وخلص، \nوبقى إسماعيل بيبكي من الجوع... \nفهي ماقدرتش تستحمل إنها تشوفه كده وهي مش قادرة تعمل حاجة...أم لطفل رضيع ابنها بيبكي جعان في صحراء وهي مش قادرة تعمل حاجة ولا عارفة تروح فين ولا فيه حد تنادي عليه يديها أكل ومية من معاه! \n ومع ذلك توكلت على الله وقامت تسعى ورا الرزق وتدور على أي حاجة ...أي أكل أو أي مية أو أي إنسان\n \nفطلعت على جبل الصفا فمالقتش حاجة .. وطلعت على جبل المروة مالقتش حاجة ، \nفضلت تطلع وتنزل من الجبل ده للجبل ده... سبع مرات متتالية، \nولكم أن تتخيلوا..امرأة وحيدة من غير سند أو راجل يشيل عنها.. جعانة...عطشانة...مرهقة.. هزيلة.. ابنها بيعيط من الجوع طالعة نازلة من جبل للتاني في عز الحر!\n \nوفي وسط كل التعب والضعف ده بتبص بعنيها كل شوية على إسماعيل  من بعيد عشان تطمن عليه، \nوفجأة وهي بتبص عليه في مرة تلاقي المية بتطلع من عند رجله، \nوكان جبريل عليه السلام ضرب الأرض بطرف جناحه فتفجر منها الماء، \nفلما شافت المية راحت جري وقعدت تحوط عليه ابإيديها وتقول زُم زُم  \nعشان كده اتسمى بئر الماء بزمزم ، والمية \nعمالة تفور، \nوبقت تاخد من المية تحط في القِربة إللي كانت معاها \nوبدأت الطيور\n تتجمع لأن الطيور بتيجي على المكان إللي فيه مية، \nفي الوقت ده كان في قبيلة من جُرْهم معدية من المكان فشافوا الطيور وقالوا أكيد في مية في المكان ده خلونا نروح نشوف\n \nوقبيلة جُرهم دي من العرب العاربة يعني العرب إللي بيتكلموا اللغة العربية ... \nفالعرب قبل إسماعيل عليه السلام اسمهم العرب العاربة وكان منهم قبائل كثير زي عاد وثمود ومدين إللي قلنا على أنبياؤهم قبل كده إنهم عرب\n \n☆فاكرين لما قلنا إن هود وصالح وشعيب عليهم السلام كانوا عرب\n \nكان من القبائل العربية دي قبيلة جُرْهم إللي كانت معدية وقت فوران ماء زمزم ، \nكان سد مأرب بتاعهم انهار، فرحلوا عن بلدهم يبحثوا عن مكان جديد يعيشوا فيه ويكون فيه حياة وزرع ومية وغيره.. \nفلما وصلوا عند هاجر وإسماعيل وشافوا المية قالوا لها: \nممكن نسكن في المكان هنا معاكم ؟ \nقالت لهم ماشي بس بئر الماء دة بتاعي أنا.. ملكي أنا\n \nقالوا : أكيد.. \nوبعتوا بقى جابوا أهلهم واستقروا في مكة عند بئر زمزم. \n☆ملحوظة:\nهاجر مش قصدها إن المية بتاعتها يعني هتمنع عنهم الماء، لأ طبعا، وإلا كانوا هيوافقوا يقعدوا جنبهم على أساس إيه! ما كانوا يسكنوا في أي مكان تاني مافيهوش مية\nلكن هي فقط بتثبت مِلكية البئر عشان محدش ينازعهم عليها.\nبدأ إسماعيل عليه السلام يكبر ويتعلم منهم اللغة العربية ، \nوكان هو أول من نطق باللغة العربية الفصحى المعروفة إللي نزل بيها القرآن، \nوالعرب ورثوا الفصاحة عن إسماعيل عليه السلام، \nفالعرب إللي جم بعد كده من ذرية إسماعيل عليه السلام ومنهم محمد ﷺ اسمهم العرب المُستعربة، لأنهم اتعلموا اللسان العربي من قبيلة جُرهم \n●بالنسبة لإبراهيم عليه السلام كان بيتكلم باللغة الآرامية،  أو السريانية، \n وهي لغة بين اللغة العربية القديمة ، واللغة العربية بتاعتنا إللي إحنا عارفينها: \"لغة القرآن\" ، \nوبالمناسبة اللغة العبرية بتاعة اليهود هي فرع من فروع اللغة العربية القديمة \n \n،المهم \nإبراهيم عليه السلام كان بييجي يزور هاجر وإسماعيل عليه السلام كل فترة -وقيل كل شهر.. \nوكان إبراهيم عليه السلام بيحب إسماعيل لأنه كان ولده الوحيد ساعتها وكان ابنه البكر وكمان اتولد بعد زمن طويل فكان له مكانة عظيمة في قلبه زي ما قلنا، \nلكن إبراهيم عليه السلام كان خليل الله\n \nوالخِلّة دي منزلة عظيمة لازم يكون فيها القلب فاضي من حب كل شيء إلا حب الله...فعشان كده ربنا ابتلى إبراهيم ابتلاء عظيم جدا \n \nربنا أراد إنه يختبر إبراهيم عليه السلام في صدق محبته له عز وجل ويَعلم وُيظهِر مين إللي حبه في قلب إبراهيم عليه السلام أكبر: \nحبه هو عز وجل ولاّ حب ابنه إسماعيل...هل هيقدم حبه لابنه على أوامر الله ولا هيعمل العكس\n \nطبعا إحنا عارفين إن رؤيا الأنبياء وحي\n \nفإبراهيم عليه السلام رأى رؤيا إنه بيذبح ابنه\n \n\"فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يَابُنَيَّ إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ\" \nطبعا ده معناه إن ربنا بيؤمره إنه يذبح ابنه\n \nمتخيلين الصدمة إللي إبراهيم عليه السلام فيها\n \nده احنا بيجيلنا الأمر من ربنا في حاجات بسيطة جدا ومع ذلك بنحس إنها تقيلة وبنقول مش قادرين وبنقعد ندور على أعذار\n \nده جاله الأمر بذبح ابنه البكر الوحيد إللي اتولد له بعد ٨٤ سنة\n \nيعني مش إن ابنه هيموت لأ ده إنت إللي هتذبحه يا إبراهيم بإيدك\n \nطيب هيعمل إيه ويتصرف إزاي\n \nإبراهيم عليه السلام لإنه يعلم علم اليقين إن ابنه ده مش بتاعه لأ ده وديعة عنده إلى وقت معين وإن ربنا هو إللي رزقه بيه، \n سلم الأمر لله بكل رضا وطمأنينة و بدون أي تردد، وراح لإسماعيل عليه السلام وأخبره بالموضوع، \n\" فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يَا بُنَيَّ إِنِّي أَرَىٰ فِي الْمَنَامِ أَنِّي أَذْبَحُكَ فَانْظُرْ مَاذَا تَرَى\" \n وكان ساعتها إسماعيل كبر وبقى بيعتمد على نفسه ويشوف مصالحه ويدرك ويميز الكثير من الأمور ودة معنى كلمة \"بلغ معه السعي\"،\n☆وهنا إبراهيم عليه السلام بيعلمنا منهج تربوي مع عيالنا وهو إننا نستشيرهم في الأمور إللي تخصهم... \nيعني إبراهيم عليه السلام ماراحش أخد إسماعيل عليه السلام وذبحه وخلاص انتهى الموضوع\n \nلأ، مع إن ده أمر إلهي مفيش فيه أي مجال للعصيان، ومع ذلك أشركه معاه في الموضوع لأنها حاجة خاصة بيه، وعشان يُشرك ابنه معاه في اجر الصبر والإحتساب\nوكمان لإن ابنه راشد بما يكفي عشان يتحاور وياخد ويدي ويقرر بحكمة في الأمر اللي هيُستشار فيه،\nفمتقولش لابنك إعمل إللي بقولك عليه وخلاص ويكون أمر يخصهم ويمس أمورهم الشخصية بالفعل \n \nماتقررش بالنيابة عنه هياكل إيه ويلبس إيه ويحب إيه ويكره إيه وباقي أموره من غير ما تاخد رأيه فيها، \nطبعا لو رأيه غلط توضح له الصح إيه وتتحاور معاه وتعلمه التفكير المنطقي الصائب الراشد بيكون إزاي،\nولو الأمر أكبر من مستوى تفكيره وقراراته الراشدة فطبعا ده خارج كلامنا\nزي إنك مثلا تاخد رأي ولادك وهما لسة أولى ابتدائي هل تخرجوا من التعليم ولاّ تكملوا،\nلإن معروفة الإجابة هتكون إيه طبعا \n \nيعني بشكل عام وباختصار: \nما تخليش ابنك معتمد عليك في تقرير أموره في كل حاجة تخصه..كبّره وعلمه إزاي يتحمل المسؤولية ويصنع قرار وكل موقف بتقديره بقى حسب كل أسرة وكل سن وكل بيت\n \nفإسماعيل عليه السلام رد بكل صبر واستسلام لله وقال: يا أبتِ افعل ما تؤمر ستجدني إن شاء الله من الصابرين،\nوهنا إسماعيل عليه السلام استعان بربنا\nمقلش انا أدها وأقدر أستحمل واعتمد على قوته... لأ ..ده قال إن شاء الله عشان ربنا يثبته على البلاء العظيم ده،\nفتقبل أمر ربنا بكل صبر ويقين \nفلما خلاص حطه على وشه وأخفى إسماعيل عليه السلام وشه عشان أبوه متتغلبش عليه الشفقة فيتراجع عن الذبح،\n\" قَالَ يَاأَبَتِ افْعَلْ مَا تُؤْمَرُ سَتَجِدُنِي إِنْ شَاءَ اللَّهُ مِنَ الصَّابِرِينَ * فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ \"\nنرجع لإسماعيل عليه السلام، \nإسماعيل عليه السلام رد بكل صبر واستسلام لله وقال: يا أبتِ افعل ما تؤمر ستجدني إن شاء الله من الصابرين، \nوهنا إسماعيل عليه السلام استعان بربنا بإنه أثبت اعتماده وتوكله في الثبات على الله عز وجل\n \nمقلش \"انا أدها وأقدر أستحمل\"، واعتمد على قوته وثباته الانفعالي من دون الله... لأ .. \nقال 《إن شاء الله》 هتلاقيني صابر وثابت يا أبي، استعان بالله عشان ربنا يثبته على البلاء العظيم ده، \nوتقبل أمر ربنا بكل صبر ويقين \n \n \"فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ \" \nخلاصإبراهيم حطه على وشه، وأخفى إسماعيل عليه السلام وشه عشان أبوه ماتتغلبش عليه الشفقة فيتراجع عن الذبح، \nتخيلوا معايا كده، \nأب ماسك في إيده سكينة ...والابن قاعد في الأرض مستسلم تماما للذبح وفعلا يبدأ إبراهيم بذبح ابنه .. \nلكن فجأة..!! السكينة مش بتقطع!\n \nزي النار اللي مش بتحرق كده،\nلإن زي ما قلنا: الحاجات مالهاش القدرة بذاتها ولكن بأمر الله فقط، مالك الملك..\n \nإبراهيم عليه السلام استغرب !! \nالسكينة مش راضية تذبح!!\n \n وإسماعيل عليه السلام مستني آخر لحظات حياته وحاسس بالسكين بتتحرك على رقبته بس مفيش ألم ولا دم ولا روحه بتطلع!! \nإيه الحكاية\n \nوفي اللحظة دي يسمعوا منادي بينادي...... \nمين هو المنادي ؟ وعايز إيه ؟\nوليه السكين مذبحتش إسماعيل عليه السلام؟\nده إللي هنعرفه الجزء الجاي"}, {"n": 13, "l": "الجزء ١٤ | إبراهيم ٤", "u": "https://www.facebook.com/groups/710210019782034/permalink/725192768283759/", "t": "#قصص_الأنبياء\n#الحلقة_الرابعة_عشرة\n#قصة_إبراهيم(٤)\n#البشارة_بإسحاق\nوقفنا المرة إللي فاتت عند دهشة إبراهيم عليه السلام من  السكينة التي لا تذبح\n وصوت المنادي إللي بينادي على إبراهيم عليه السلام:\n يا إبراهيم قد صدقت الرؤيا،\n\"وَنَادَيْنَاهُ أَنْ يَا إِبْرَاهِيمُ *قَدْ صَدَّقْتَ الرُّؤْيَا\"\nيعني ربنا قال لإبراهيم إنت نفذت المطلوب منك خلاص ونجحت في الاختبار العظيم ده، \nفالتفت إبراهيم عليه السلام لقى كبش ضخم عشان يذبحه فداء لإسماعيل عليه السلام، يعني يتم ذبحه بداله \nوخلاص البلاء انتهى وإبراهيم عليه السلام لم يذبح إسماعيل\n¤إيه ده\n...طيب وكان لازمته إيه الموضوع من الأول مادام كده كده ربنا لا يريد قتل إسماعيل عليه السلام\n \nلازم يعني الإبتلاء الشديد ده\n!! \nأيوة لازم اختبار وتمحيص، وعشان كده احنا جينا في الدنيا ليبلوكم أيكم أحسن عملا \nربنا لا يبتلي عباده المؤمنين ليعذبهم أبدا\n \nلكن كمان ربنا مش بيحاسبنا ولا بيجازينا بسابق علمه فينا...يعني لااااازم نشتغل ويبقى لينا عمل عشان على أساسه يحاسبنا فيعاقبنا أو يكافئنا، \nإزاي ربنا هيكافئ إبراهيم عليه السلام ويرفع درجته بحاجة هو معملهاش لسه لكنه عارف عز وجل إنه هيعملها\n \nمثال : إنت مكتوب لك عند ربنا إن ليك أجر الصابرين والكاظمين الغيظ، \nإزاااااي هتاخد الأجر ده إلا لو ربنا ابتلاك بشخص سليط اللسان مش بيشوفك غير لما يحرق دمك\n \nربنا مثلا كاتب لك أجر المجاهدين لأنفسهم...إزاااي هتاخد الأجر ده إلا لو إنت عمال تجاهد نفسك وشيطانك على الطاعة وبعيد عن المعصية...وهكذا\n \nوكذلك إبراهيم  عليه السلام إزاي قصته هتكون مضرب للمثل في التسليم لأمر الله إلا لو اتحط في الإبتلاء ده،\nإزاي مكانته كخليل للرحمن هتيجي من غير ما يضحي بأغلى ما يملك في حياته في الوقت ده وهو ابنه\nطب فاكرين لما قلنا إن سارة غارت جدا من هاجر وابنها إسماعيل\n \nإزاي قلب سارة هيهدى وتتحول قسوة الغيرة إلى شفقة وحب لو ماحصلتش الحادثة دي،\nوإزاي كانت هتكون مناسك الحج لولا الحادثة دي\n \nفمتفكرش أبدا أبدا إن ربنا بيقدّر الأمور عبثًا والعياذ بالله ..لأ \nده كل حاجة محطوطة في مكانها بالضبط...وكل حاجة متسجلة\n \nوجع قلبك ودموعك وقهرتك وظلم الناس ليك و...و...\nكل ده ربنا مقدره عشان يشيل من عندك ذنب أو يطهر قلبك ويعلمك الصح من الغلط فتزكي نفسك  أو يرفع درجتك في الجنة، قلنا ربنا لا يبتلي ليُعذب ...فما تقلقش\n \nبعد ما ذبح إبراهيم عليه السلام الكبش فداءا لإسماعيل عليه السلام ورجعه لأمه هاجر رجع لفلسطين عند سارة من تاني\nوكان إبراهيم عليه السلام ييزور إسماعيل وهاجر كل فترة زي ما قلنا، \n وكان إسماعيل عليه السلام تزوج من قبيلة جُرهم بعد موت أمه هاجر، فلما زاره إبراهيم عليه السلام ومالقاهوش  \n ولقي إمرأة وسألها عن إسماعيل ، قالت له مش موجود، راح يصطاد لنا صيد ، \nوكان إسماعيل بيخرج برة الحرم عشان يصطاد ، \n فسألها عن حالهم بشكل عام عاملين إيه.... \nفقالت له العيشة وحشة ومعندناش إللي يكفينا والحالة كرب و و و و... وقعدت تشتكي له من الحياة الزوجية تحت كنف إسماعيل\n \nفقال لها لما زوجك ييجي سلمي عليه وقوليله غير عتبة بابك \n \nفلما رجع إسماعيل عليه السلام كإنه حس إن في حد جه، فسأل زوجته: حد جه النهاردة \n \nفقالت له أيوة جالنا شيخ شكله كذا وكذا -ووصفته لإسماعيل عليه السلام- وسأل عليك وسأل عن حالنا فحكيت له، \nفسألها ..طيب هو وصاكِ بحاجة\n \nقالت : قال لي بيبلغك سلامه وبيقولك غير عتبة بابك، \nفقالها ده أبويا وووصيته هي إني أفارقك.. \n وطلقها فعلا، \nوتزوج امرأة تانية من جُرهم، \nبعد مدة جه إبراهيم عليه السلام يزور إسماعيل مرة تانية وماكنش موجود و ردت عليه إمرأة تانية، فسألها عن إسماعيل فقالت إنه خرج يصطاد ، يعني في الشغل بلغة زماننا\n \nفسألها عن حالهم وعيشتهم فحمدت ربنا وقالت إن ربنا موسع عليهم، فسألها بياكلوا إيه قالت : اللحم وسألها بيشربوا إيه: قالت الماء ، \nفدعا لهم إبراهيم عليه السلام بالبركة \nوقالها :لما زوجك يرجع سلمي عليه وقوليله ثبت عتبة باباك، \nفلما رجع إسماعيل عليه السلام سأل زوجته حد جه النهاردة\n \nقالت أيوة جالنا شيخ كبير -ووصفته ومدحته- وسأل على حالنا قلتله إننا كويسين، \nفقال لها وصاكِ بحاجة\n....قالت له: بيسلم عليك وبيقولك ثبّت عتبة بابك، \nفقال لها ده أبي ، وإنتي العتبة إللي أمرني إني أثبتها، يعني بيوصيني ما أفارقكيش\n¤وييجي هنا سؤال\n هم ليه بيسموا المرأة عتبة \n \nلإن عتبة الباب والزوجة بيشتركوا في نفس الصفات الحميدة الطيبة: من حفظ البيت وستره وصيانة إللي جوة البيت من كل سوء برة البيت\n \n¤طيب سؤال تاني \n \nهو إسماعيل عليه السلام يسمع كلام أبوه كده على طول بدون ما يراعي مشاعر زوجته\n \nطب وهي مراعتش ليه مشاعر زوجها لما واحد غريب ماتعرفوش يسألها عن حالهم وتقعد تشتكيله\nيعني بغض النظر إن ده نبي \nهل ينفع إن المرأة تقعد تشتكي من زوجها للناس الرايح والجاي بصفة عامة؟ ... \nيعني ده راجل غريب وقالت كده فما بالنا بالقريب هتكلمه عنه إزاي؟\n \nفإبراهيم عليه السلام لما أمر إسماعيل إنه يطلق زوجته كان قراره ده بسبب شكوى الزوجة وعدم رضاها برزق الله وسخطها الواضح على العيشة، \n فهي ماتنفعش تكون زوجة نبي ابن نبي، \nومش أي أنبياء هما ده واحد الذبيح إسماعيل عليه السلام،  والثاني أبوه رسول من أولي العزم من الرسل وخليل الله المستسلم لأمر الله ...الراضي بقضاء الله ... \nيعني احنا مش بنتكلم عن أي حد \n \nفإزاي تكون واحدة زي دي بتشتكي قلة الرزق و رِقّة العيش وتواضع النفقة ومش بتستر وتحفظ غيبة زوجها تكون في بيت النبوة ده\n، \nده إحنا في عُرفنا لما واحد بيبقى عايز يتزوج وهو من عيلة معروفة مش بيدور على أي واحدة كده وخلاص...لأ بيدور على صفات معينة وعيلة معينة ومركز معين وبيدقق في مواصفات الزوجة الصبورة الحمولة العفيفة اللي لسانها محترم وعينها مليانة وأخلاقها كريمة، فما بالكم بالأنبياء أفضل البشر\n \nفهو موصاهوش إنه يطلقها كده وخلاص بدون سبب معتبر،\nوإلا فهو ماطلبش منه إن يطلق الزوجة التانية هي كمان إللي لقى فيها حسن الخلق والرضا برزق الله، \nوكل ما كانت الزوجة صالحة ،كانت أكثر عونا لزوجها على أمور الدين والدنيا، وأعمق أثرا في تربية أبناء صالحين\nالمهم.. \nرجع إبراهيم عليه السلام لزوجته سارة في فلسطين \n وهنا بقى حصلت المعجزة\n \nتخيلوا معايا كده واحدة ست عجوزة عمرها ٩٠ سنة وعقيم لا تلد، وراجل عجوز عمره ١٢٠ سنة \nراحوا لمستشفى وقالوا للدكاترة هو فيه أمل إننا نخلّف\n الدكاترة ممكن يقولوا لهم إيه \n... \nإنتم نفسكم لو شفتوا موقف زي ده  قصادكم هتقولوا إيه على الراجل العجوز ده وزوجته\n \nأهو ده بالضبط كان الوضع مع إبراهيم عليه السلام وزوجته سارة، \nولكن من يتق الله يجعل له مخرجا ويرزقه من حيث لا يحتسب\n \nإبراهيم عليه السلام نفذ أمر ربنا بذبح إسماعيل من غير ما يلاقي أي حرج في نفسه من طاعة الله،\nفربنا مش بس كافؤه بإللي قلنا عليه\n، \nلأ .. \nده كمان هيحققله معجزة وهيرزقه ولد تاني من زوجته  \"سارة\" إللي كان نفسه ونفسها إنها تُنجب من زمان\nومش بس كده ..ده هيكون نبي ! \nومش بس كده... ده هيتزوج وهيخلف ، وكل ده في حياة إبراهيم عليه السلام ، وحفيده ده هيكون نبي كمان ، وابن حفيده كمان نبي\nيعني الرجل العجوز إللي مكنش عنده أي أمل في ابن واحد  ربنا رزقه بولد واتنين وهيشوف أحفاده وهتتكاثر ذريته وتملأ الأرض وهيكونوا أنبياء،\nومش بس كل ده \nلأ ده كمان باقي الأنبياء إللي هييجوا بعد كده كوووولهم هيكونوا من ذرية إبراهيم عليه السلام\n \nعشان كده إبراهيم عليه السلام بيُلقب بـ ((أبو الأنبياء)) \n \nنتعلم من كده....\nإن  إللي يببذل لربنا شيء بإخلاص ربنا بيعوضه له أضعاف أضعافه ، فهو الكريم سبحانه\n \n\"وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا * وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ إِنَّ اللَّهَ بَالِغُ أَمْرِهِ قَدْ جَعَلَ اللَّهُ لِكُلِّ شَيْءٍ قَدْرًا\"\nطيب قصة الولد الثاني بدأت إزاي\nإبراهيم عليه السلام كان أول من أكرم الضيوف، \nوكان بيبحث عن ضيوف ويجيبهم عشان ياكلوا معاه في بيته، تخيلوا!\nوكان فاتح بيته للناس واحة ظليلة بحسن الضيافة والطعام والشراب، يدخلوا بيته بدون استئذان ، وده من شدة كرمه، \nلكن قعد فترة مكنش بيجيله ضيوف ، \nلحد ما دخل عليه ٣ أشخاص.... \nكانوا أجمل بشر شافهم في حياته\nلما دخلوا عليه سلموا ورد عليهم السلام وكان مستغربهم شوية لإنهم مش من البلد، \n\"هَلْ أَتَاكَ حَدِيثُ ضَيْفِ إِبْرَاهِيمَ الْمُكْرَمِينَ * إِذْ دَخَلُوا عَلَيْهِ فَقَالُوا سَلَامًا قَالَ سَلَامٌ قَوْمٌ مُنْكَرُونَ\" \nيعني قوم غيرمعروفين،\nبعد شوية سحب نفسه من وسطهم من غير ما يحسوا\n عشان يجيب لهم أكل ويضيفهم بكرمه المعتاد،\nفرجع لهم ومعاه عجل سمين مطبوخ وشهي جدا وحطه قدامهم عشان ياكلوا \n\"فَرَاغَ إِلَى أَهْلِهِ فَجَاءَ بِعِجْلٍ سَمِينٍ \nفلما شافهم مامدوش إيدهم على الأكل، قلق وخاف\n وقال لهم: \n إنتم مش هتاكلوا\n فَقَرَّبَهُ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ *فَأَوْجَسَ مِنْهُمْ خِيفَةً \".\n لإن كان من المعروف في الزمن ده إن إللي مش بياكل من الأكل بتاعهم يبقى ناوي على شر\n \n☆وهنا فائدة جميلة تبين أد إيه زمان كان عندهم مروءة ونخوة، ومن ضمن ده صيانة العيش والملح، مش هاكل من أكلك وأنا ناوي أأذيك عكس انعدام المروءة إللي بنلاقيه أحيانا في زماننا دلوقتي، تلاقي الأخ أو الأخت من دول ياكلوا مع أكل أصحاب البيت، \nولما يسيبوهم يغتابوهم ويحرضوا عليهم ويحسدوهم ويؤذوهم ويتكلموا عليهم من وراهم بكل حقد، ويرجعوا تاني ياكلوا عندهم عادي جدا ، ياكلوا عندهم وياكلو من لحمهم، ولا حول ولا قوة إلا بالله\nفالثلاثة دول طمنوه وقالوا متخفش..احنا مُرسلين لقوم لوط عشان نُهلكهم... \nفاتضح لإبراهيم إن الثلاثة دول ملائكة مش بشر طبيعيين، وعشان كده ما أكلوش من الأكل اللي متقدم لهم لإن الملايكة مبتاكلش ولابتشرب طبعا، فكانوا ثلاثة ملائكة متمثلين في هيئة بشر: هم جبريل وميكائيل وإسرافيل،\n\"قَالُوا لَا تَخَفْ إِنَّا أُرْسِلْنَا إِلَى قَوْمِ لُوطٍ\" \nكانت سارة عند المجلس عشان لو احتاج الضيوف شيء،\nفلما سمعت كلام الملائكة ضحكت وفرحت جدا إن ربنا هيُهلك القوم المفسدين المجرمين دول، \n\"وَامْرَأَتُهُ قَائِمَةٌ فَضَحِكَتْ فَبَشَّرْنَاهَا بِإِسْحَاقَ وَمِنْ وَرَاءِ إِسْحَاقَ يَعْقُوبَ \" \nفهنا الملائكة بشرتها وبشرت إبراهيم عليه السلام بإنها هتولد ولد اسمه إسحاق ...والولد ده هيكبر ويتزوج وهتشوف حفيده وهو يعقوب عليهم السلام أجمعين، \nفهنا صرخت من الدهشة وقالت يا ويلي!! أنا عقيم\n!! \nهولد وأنا عجوز عقيم وزوجي شيخ كبير في السن\n\"فَأَقْبَلَتِ امْرَأَتُهُ فِي صَرَّةٍ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌ\"!! \n\" قَالَتْ يَاوَيْلَتَى آلِدُ وَأَنَا عَجُوزٌ وَهَذَا بَعْلِي شَيْخًا إِنَّ هَذَا لَشَيْءٌ عَجِيبٌ\"!! \nفالملائكة قالت لها إنتي بتتعجبي من أمر ربنا!! \n\"قَالُوا أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ رَحْمَةُ اللَّهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَجِيدٌ \" \nيعني مفيش أي عجب إن ربنا يرزقكم الولد رغم كل الصعوبات دي، \nدي قدرة ربنا إللي مالهاش حدود ولا بيقف قصادها شيئ.\nودعت لهم الملائكة بالسلام والبركة.. \n☆ملحوظة \nكلمة ضحكت في الآية :\n\"وَامْرَأَتُهُ قَائِمَةٌ فَضَحِكَتْ فَبَشَّرْنَاهَا\"\nفي بعض المفسرين بيقولوا إن معناها حاضت، لكن أكثر المفسرين على إن ضحكت معناها الضحك المعروف.\nلما إطمأن إبراهيم عليه السلام وفرح بالبشرى، بدأ يكلم الملائكة في قوم لوط، ويقولهم: \nهتهلكوهم؟! طب ده فيهم ناس مؤمنين؟! وكمان فيهم لوط\n\"فَلَمَّا ذَهَبَ عَنْ إِبْرَاهِيمَ الرَّوْعُ وَجَاءَتْهُ الْبُشْرَىٰ يُجَادِلُنَا فِي قَوْمِ لُوطٍ\"  \nفالملائكة قالت له يا إبراهيم مفيش فايدة من الكلام، \nده أمر ربنا ومفيش فيه نقاش لا هيقدم ولا هيأخر،\nواحنا عارفين مين إللي موجود في القرية واحد واحد، \nوهننجي لوط وإللي آمنوا معاه، وهنهلك باقي القرية من المجرمين،\n\"يَا إِبْرَاهِيمُ أَعْرِضْ عَنْ هَٰذَا ۖ إِنَّهُ قَدْ جَاءَ أَمْرُ رَبِّكَ ۖ وَإِنَّهُمْ آتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ\" \nمين بقى قوم لوط ؟\nوعملوا إيه عشان يستحقوا إن ربنا يهلكهم ؟\nهنعرف الإجابة الجزء الجاي إن شاء الله\nhttps://www.facebook.com/groups/710210019782034/?ref=share"}, {"n": 14, "l": "الجزء ١٥ | إبراهيم ٥", "u": "https://www.facebook.com/groups/710210019782034/permalink/819541958848839/", "t": "#قصص_الأنبياء\n#الحلقة_الخامسة_عشرة\n#قصة_إبرهيم(٥)\n#لوط_وقومه\nكنا واقفين عند إبراهيم عليه السلام لما كان بيجادل الملائكة في قوم لوط ،والملائكة قالت إن خلاص ربنا أمر بإهلاكهم، وفعلا خرجت الملائكة متجهة إلى قرية لوط عليه السلام.\nمين همّ قوم لوط أصلا\nخلونا نرجع بالزمن شوية ... \nفاكرين لما إبراهيم عليه السلام ربنا نجّاه من النار وبعدين لوط عليه السلام آمن بيه وخرجوا مهاجرين من بلدهم؟ \n( ولوط عليه السلام هو ابن أخ إبراهيم عليه السلام،) \nوفاكرين بعدها لما إبراهيم عليه السلام سكن الشام مع سارة،\nأهه في الوقت ده لوط عليه السلام سكن في مدينة اسمها سَدُوم، \nعند مكان اسمه \"البحر الميت\" في زماننا دلوقتي، \nوأهل سدوم اسمهم \"المُؤْتَفِكة\"، \nوالمؤتفكة في اللغة العربية معناها: كل ما هو مصروف عن وجههِ وحاله إللي المفروض إنه يكون عليه.. \nومعناها في القرآن: هُم قومُ لوط المُنقلبة قُراهُم عليهم عاليها سافلها \nالمهم.. \nكانت المدينة دي يتبعها قُرَى حواليها، \nأهل المدينة دول كانوا كفار.. ومش بس كده، \nلأ دول كمان كانوا بيعملوا حاجة بشعة محدش عملها قبل كده\n \nوهي إن الرجال كانوا يأتون الرجال...يعني الرجل يُعاشر الرجل...ودي حاجة ضد الفطرة، عكس الوجه والحال اللي ربنا خلق البشر بيه وإللي المفروض يكونوا عليه. \nيعني ربنا خلق الرجل والمرأة مناسبين لبعض عشان يتزوجوا ويجيبوا أطفال ويستمر النسل\n \nلكن لما الرجل يتزوج الرجل النسل هينقطع والأمراض هتنتشر،\nوالمشكلة إن مش واحد ولا إتنين إللي شَذُّوا عن الفطرة اللي ربنا فطر الناس عليها..لأ ... دي القرية كلها كده والعياذ بالله\n \nوكانوا بيعملوا الفاحشة دي قصاد بعض عادي في النوادي \nوكانوا يخرجون الريح علانية أمام بعض ويتضاحكون على كده، ومكانوش بيستحوا من أي شيء من أفعالهم الخبيثة القذرة دي، \nوكانوا كمان قُطّاع طرق، يقطعوا الطريق على المسافرين ويفعلوا بهم الفاحشة، \n \"أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ وَتَقْطَعُونَ السَّبِيلَ وَتَأْتُونَ فِي نَادِيكُمُ الْمُنْكَرَ \" \nيعني كانوا أخبث الخلق فعلا، \nويُقال والله أعلم إن إللي خلّاهم يعملوا الفاحشة مع الرجال إن كان عندهم بساتين وثمار موجودة على الطريق وحصل لهم قحط وجوع فقالوا لبعض لو منعنا الثمار إللي على الطريق دي عن المسافرين وأبناء السبيل هنقدر نعيش، \nفقالوا ونمنعها إزاي\n \nفقالوا نخلي من عاداتنا إن أي رجل غريب ييجي البلد نسرقه ونفعل به الفاحشة وبكده محدش هييجي البلد \n \nوفعلا عملوا كده واعتادوا على الموضوع لحد ما بقى في طبعهم، \nفربنا أرسل لهم لوط عليه السلام، بالهداية عشان يخرجهم من الظلمات دي إلى النور. \nبدأ لوط عليه السلام أول حاجة خالص زي أي نبي مُرسل يَدعوهم لعبادة الله وحده،\nيعني بدأ معاهم بالأَوْلى والأهم، فأهم حاجة دلوقتي إنهم يؤمنوا بالله ويعبدوه، \nعشان لما ده يتحقق هيبقى سهل يستسلموا لأوامره ويتقوه ويطيعوه بدون عناد ومكابرة .\n\"إذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلا تَتَّقُونَ۩ إِنِّي لَكُمْ رَسُولٌ أَمِيْنٌ۩ فَاتَّقُوا اللهَ وَأَطِيْعُون\" \n☆وهنا في فائدة وهي إن لازم يكون عند الدعاة إللي بيدعوا الناس وبينصحوهم حاجة اسمها فِقه الأولويات،\nيعني نعرف نبدأ بإيه معاهم الأول قبل أي حاجة تانية، حسب ترتيب الشرع للأولويات الشرعية.. \nيعني مثلا زي بالضبط لما تيجي أخت تنصح بنت مش بتصلي ومش لابسة حجاب هتكلمها في إيه الأول؟ \nهتكلمها في الصلاة الأول لأنها الأصل ورسول الله ﷺ قال: \n\"العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر\"\nطيب هل معنى كده إن الحجاب الشرعي مش مهم\nلأ هو مهم بس الصلاة أهم دلوقتي\n \nوهو ده فقه الأولويات الشرعية.\nالمهم،\nلوط عليه السلام لما بدأ دعوته لقومه بإنهم يعبدوا الله وحده ولا يشركوا به شيئا، وقالهم إنه مش عايز منهم مقابل لدعوته ولا أجر،\nهو بينصحهم عشان مصلحتهم هم فقط في الدنيا والآخرة \n\"وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلاَّ عَلَى رَبِّ العَالَمِيْنَ\" \n وحذرهم إن ربنا هينزل فيهم العذاب لو استكبروا ورفضوا الهدى، \nوطبعا ناس زي دول، تتوقعوا  هيكون رد فعلهم إيه\n \n\"قَالُوا لَئِنْ لَّمْ تَنْتَهِ يَا لُوطُ لَتَكُونَنَّ مِنَ المُخْرَجِيْنَ\" \nيعني قالوا للوط عليه السلام لو مابطلتش كلامك ده هنطردك برة البلد\n \nلكن لوط عليه السلام استمر يدعوهم ويأمرهم بالمعروف وينهاهم عن المنكر سنين، ويعيد ويزيد ويقول:\n\"أَتَأْتُونَ الذُّكْرَانَ مِنَ العَالَمِين ۩ وَتَذَرُونَ مَا خَلَقَ لَكُمْ ربُّكُمْ مِّنْ أَزْوَاجِكُمْ بَلْ أَنْتُمْ قَومٌ عَادُونَ\" \nلما كان بيبقى في ناس معدية على الطريق من المسافرين كان لوط بيخبيهم عنده ويمشيهم في الليل في الخفاء بعيد عن أعين قومه أهل الفواحش، عشان لو شافوا الرجال دول هياخدوهم ويغصبوهم على فعل الفاحشة معهم، \nواستمر الوضع على كده...قوم لوط عليه السلام يعملوا الفواحش ومستمرين في الكفر والظلم والتعدي على الناس \nولوط يدعوهم لعبادة الله وترك الفواحش، \nلحد ما المجرمين زهقوا وقالوا اطردوا لوط وأهله من القرية \n \n☆إيه تهمته ياجماعة عشان تطردوه\n \nالتهمة هي: إنه بيدعونا إننا نكون طاهرين زيه\n\"أَخْرِجُوهُم مِّنْ قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُون \" \n¤لو بصينا في الواقع بتاعنا هنلاقي إن بيحصل كده بالضبط \n \nهتلاقوا الإنسان إللي بيدعوا للخير الناس بتنبذه غالبا هو وأقرانه ويعملوا منهم كتلة غريبة زي الجسد الغريب كده على المجتمع،\nهتلاقوا إللي بيؤمروا بالمعروف وينهوا عن المنكر الناس بتبص لهم باستنكار وبتستغربهم وبتنفر منهم ومش بعيد يقولوا لهم في وشهم ارحمونا خربتوا البلد\nإيه التشدد ده...إيه التخلف ده.... إنتم بتحرموا وتحللوا على مزاجكم...الدين يسر\n... إلى آخر الكلام اللي كلنا عارفينه\nوالحقيقة بقى إنهم بيعملوا كده عشان الكلام مش على مزاجهم وكمان اتعودوا على الغلط وشربوه لحد ما بقى جزء من أساسهم ففطرتهم انتكست وبقو يتخيلوا إن هو ده الأصل، وإن الحق والنقاء هو الشاذ\nفبقوا شايفين الباطل حق والحق باطل... \nوأظن انتم شايفين الواقع بتاعنا عامل إزاي سواء على مستوى الأفراد يعني الناس إللي حواليكم، أو حتى مستوى الحُكام\n \nقوم لوط قالوا إنت عمال تقولنا إن ربنا هيبعت علينا عذاب لو مبطلناش إللي بنعمله \n \nهو فين العذاب ده، لو إنت فعلا صادق هاته \n\"فَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا ائْتِنَا بِعَذَابِ اللَّهِ إِن كُنتَ مِنَ الصَّادِقِينَ\"\nفلما وصل لوط للمرحلة المتأخرة خالص دي دعا ربنا إنه ينجّيه وأهله منهم ومن كيدهم،\n\"قَالَ رَبِّ انصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ\"\nفربنا أرسل الملائكة الثلاثة عشان يهلكوا قرية قوم لوط: جبريل وميكائيل وإسرافيل إللي قلنا عليهم المرة إللي فاتت  إنهم وهمّ في طريقهم لقرية لوط مروا على إبراهيم يبشروه بهلاك المجرمين دول ويبشروه بإسحاق ويعقوب ذرية له من النبيين.\nنرجع بقى لقصة إبراهيم بعد ما ربطنا الأحداث ببعض \nالملائكة بعد ما بشرت إبراهيم عليه السلام وزوجته سارة بالبشارتين الرائعتين دول خرجوا من عندهم متجهين لقرية سَدوم استجابةً لدعوة لوط عليه السلام،\nكانت الملائكة في صورة بشر كأجمل ما رأت العيون، \nودي كانت طبيعة الملائكة لما يتمثلوا في هيئة بشر بيكونوا في أجمل الصور، \nبعكس الشياطين لو تمثلوا في صورة بشر بيكونوا في أقبح الأشكال، \nفلما وصلوا عند قرية سدوم شافتهم ابنة لوط عليه السلام وكانت مؤمنة، \nفعرفت إن لو قومها المجرمين شافوا الشباب اللي شكهم حلو دول مش هيسيبوهم، \nفراحت على طول لأبوها لوط عليه السلام وقالت له إن في شباب من أجمل ما رأت داخلين القرية وإن قومها لو شافوهم هيخطفوهم ويفعلوا معهم الفاحشة\nفخرج لوط عليه السلام بسرعة وراح لهم وقال لهم إنتم إيه إللي جابكم القرية دي بس أهل القرية دي أخبث الناس وهيؤذوكم\nوحاول إنه يبعدهم عن القرية بس هما صمموا إنهم يدخلوا القرية، فمكنش قصاده حل غير إنه ياخدهم عنده في البيت، \nكل ده وميعرفش لسه إنهم ملائكة جاية لإيقاع العذاب بالقرية،\nمتخيل كده ... مجموعة شباب مطلوبين من أهل البلد لو عرفوا إنهم هنا مش هيسيبوهم، \nوإنت أخدتهم عندك البيت عشان تخبيهم منهم، \nمتخيل قلبك هيكون عامل إزاي؟\nمتخيل الرعب إللي هتكون فيه لو كشفوا أمرك وهمّ أصلا عاوزين يطردوك، \nمتخيل ساعتها إنهم ممكن بالفعل ياخدوك إنت كمان معاهم ويؤذوك عقابا ليك على ده\n \nأهه ده كان حال لوط عليه السلام\n \nوالقرآن وصف حاله ده بدقة: \n\"سِيْءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعاً وَقَالَ هَذَا يَوْمٌ عَصِيْبٌ\" \nساءه مجيئهم وضاق صدره من خوفه عليهم وقال ده يوم شديد وصعب،\nلأنه كان مفكر إن قومه المجرمين هيتغلبوا عليه ويوصلوا لضيوفه الثلاثة ويؤذوهم وربما يؤذوه معاهم، \nوفجأة لقى قومه جايين جري ورا بعض وعمالين يخبطوا عالباب بقوة لدرجة إنهم كانوا هيكسروا الباب،\n\" وَجَاءَهُ قَوْمُهُ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا يَعْمَلُونَ السَّيِّئَاتِ\"\nإيه ده\n...هم عرفوا منين\n \nكانت زوجة لوط عليه السلام هي إللي قالت لهم، \nكانت بتشعل نار برة البيت عشان تعرفهم لما يكون لوط عنده ضيوف رجال، زوجة خاينة للأسف\n \nخانت زوجها في الدين، وخانت زوجها في كشف السر، \nودي تاني زوجة تخون زوجها من الأنبياء، الأُولى كانت زوجة نوح عليه السلام \n\" ضَرَبَ اللَّهُ مَثَلًا لِلَّذِينَ كَفَرُوا اِمْرَأَةَ نُوحٍ وَامْرَأَةَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتَاهُمَا \"\n☆والخيانة هنا مش خيانة عِرض، لأن ربنا حفظ أعراض الأنبياء من ده،\nوعلى فكرة صور خيانة الزوجة لزوجها متنوعة،\nفالمرأة ممكن تخون زوجها في المشورة، يعني يستشيرها في حاجة وشايفة إنها مش من مصلحتها إنها تقوله الرأي الصح فتقوله الرأي الغلط مع إن رسول الله ﷺ  يقول:\n \"المستشار مُؤتمن\" \nوممكن تخون زوجها في كشف سره أو إنها تحكي عن حياتها معاه وأسراره،\nيعني يقول لها على حاجة فتروح هي تقول لمامتها وأختها وصاحبتها وتنشر على فيسبوك للعالم كله، \nمع إن رسول الله ﷺ قال: \"المجالس بالأمانة\" \nوانتم طبعا عارفين إن أحب الناس من الرجال لرسول الله ﷺ هو أبو بكر الصديق رضي الله عنه، \n وهو أبو السيدة عائشة، \nومع ذلك لما رسول الله ﷺ قال للسيدة عائشة على مكان الغزوة إللي كان رايحها، \nومقلش لحد غيرها وسألها ابو بكر الصديق ماردتش عليه، \nمع إنه أبوها وصاحب رسول الله ﷺ وهي عارفة إن رسول الله ﷺ هيقول له، \nومع ذلك مقالتلهوش حاجة عنها من شدة حرصها على صون السر والخبر بينها وبين زوجها ﷺ\nفالخلاصة إن الخيانة مش بس خيانة في العِرض زي ما الناس فاهمة.\nالمهم،\nقوم لوط قعدوا يخبطوا جامد على الباب، ويطلبوا من لوط إنه يفتح لهم،\nلوط عليه السلام فتح لقومه الباب وقعد ينصحهم تااااني بإن إللي بيعملوه ده غلط، \nوإداهم الحل البديل إللي يشجعهم بيه على الهجرة من المعصية والحرام إلى الطاعة والحلال ، \nوعرض عليهم إنهم يتزوجوا بنات القرية بدل الرجال،\n\" قَالَ يَا قَوْمِ هَٰؤُلَاءِ بَنَاتِي هُنَّ أَطْهَرُ لَكُمْ\" \nفقالوا له: انت عارف كويس أوي إحنا عايزين إيه، \nواحنا مش عايزين نساء القرية\n \nفحاول لوط عليه السلام إنه يحرك فيهم النخوة وقالهم اتقوا الله وبلاش تفضحوني قصاد ضيوفي ...هو مفيش فيكم واحد عاقل\n\"فَاتَّقُوا اللَّهَ وَلَا تُخْزُونِ فِي ضَيْفِي أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ\" \nوطبعا لا حياة لمن تنادي\nإلتفت لوط لضيوفه وقال لهم بحسرة وحزن لو أنا عندي القوة الكافية كنتم هتشوفوا  إزاي كنت هدافع عنكم... \nبس زي مانتم شايفين أنا لوحدي قصاد القرية كلها، \nخلال الفترة دي كلها والرزع والهرج والمرج والصراخ والحوارات والشد والجذب ده كله، سبحان الله كان الشباب التلاتة هاديين ومش بيتكلموا \n \nفلما خلاص وصل الموضوع لأقصى درجاته اتكلموا وقالوا: \nيا لوط إنا رُسل ربك ماتخفش ماحدش هيقدر يؤذيك ولا يؤذينا\n \n\"قَالُوا يَا لُوطُ إِنَّا رُسُلُ رَبِّكَ لَنْ يَصِلُوآ إِلَيْكَ\"\n وهنا عرف لوط إن دول ملائكة وعرف خلاص إن عذاب الله واقع لا محالة على القوم المجرمين \nودي كانت آخر فرصة لقوم لوط.. فلما حاولوا يتعدوا في بيت لوط على الشباب إللي هما في الأصل ملائكة، \nخلاص استحقوا العذاب.. \nفهنا جبريل عليه السلام قام وضرب على وجوههم بطرف جناحه فأصابهم بالعمى\n\"وَلَقَدْ رَاوَدُوهُ عَنْ ضَيْفِهِ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا عَذَابِي وَنُذُرِ\" \nوقعدوا يتخبطوا في بعض ومش شايفين حاجة ومشيوا،\nمش مثلا يتعظوا بالعمى المفاجيء ده ويؤمنوا ويقفوا عند حدهم\nلأ ده وهم ماشيين قعدوا يتوعدوا لوط عليه السلام بسبب إللي حصل لهم ده وإنهم مشيوا من عنده من غير ما يحققوا غرضهم الخبيث\nالملائكة بقى قالت للوط خد أهلك واطلع برة القرية وابعد ومحدش يبص وراه،\n احنا هنهلكهم الصبح..فقال لهم لوط مادام هتهلكوهم خلاص ما تهلكوهم دلوقتي \n \nفقالوا له معادهم الصبح...والصبح قريب\n \n\"فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ اللَيْلِ وَلاَ يَلْتَفِتْ مِنْكُمْ أَحَدٌ إِلاَّ امْرَأَتَكَ \n إِنَّهُ مُصِيْبُها مَآ أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ الصُّبْحُ أَلَيْسَ الصُّبْحُ بِقَرِيْبٍ\" \nفلما جه وقت الصبح وكان لوط عليه السلام خرج من القرية مع بناته ومحدش من أهل القرية كان آمن به حتى زوجته، \nربنا بعت عليهم حجارة من سجيل .. \nسبحان الله كل واحد كان اسمه مكتوب على الحجارة دي تنزل عليه فتقتله\n \nوقام جبريل عليه السلام برفع المدينة بالقرى التابعة ليها لحاااااد السماء الدنيا -حتى يُقال إن أهل السماء الدنيا سمعوا أصوات الحيوانات في القرية، وبعدين راح قالبها وموقعها على الأرض \n \n\"فَلَمَّا جَاءَ أَمْرُنَا جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ\" \n\"وَالْمُؤْتَفِكَةَ أَهْوَىٰ*فَغَشَّاهَا مَا غَشَّىٰ\"\n☆وهنا في نقطة شرعية مهمة\nوهي إن مَن يعمل عمل قوم لوط حدّه القتل\nوالصحابة اختلفوا في طريقة القتل ...قال البعض يترمى من مكان عالي،\nوقال البعض...إن يُسحب عليه جدار يعني يوقعوا عليه جدار  ويُقتل...لأن الفعل ده 《إتيان الرجال للرجال كشهوة من دون النساء وإتيان النساء للنساء كشهوة من دون الرجال》\nأشد عند الله من الزنا\nوطبعا ربنا حرم أي حاجة ممكن تؤدي تؤدي وتوصل للمنكر ده فقال رسول الله ﷺ :\n\"لعن الله المُخَنّث من الرجال والمُتَرجّلات من النساء...أخرجوهم من بيوتكم\"\nوالمخنث من الرجال هو المتشبه بالنساء سواء في اللبس أو طريقة المشي أو حتى في طريقة الكلام... \nفاللي الشباب بيعملوه دلوقتي إنهم بيعملوا برامج بيقلدوا فيها البنات ويلبسوا لبس نسائي ويتكلموا بأسلوب النساء ده حرام ، \nحتى النساء لا يجوز لها إنها تتشبه بالرجال لا في اللبس ولا الكلام ولا طريقة المشي... \nلأن الموضوع ده فيه لعن وهو من كبائر الذنوب، ولما الناس تهاونت فيه انتشر للأسف في بلاد المسلمين الشذوذ إللي هو فعل قوم لوط\n \nإحنا شريعتنا مختلفة عن الشرائع إللي فاتت لإن مفيش رسالة تانية أو رسول تاني بعد رسول الله ﷺومافيش إهلاك للأمم بذنوبها مباشرة زي الأمم السابقة،\n لأ ،بعد الرسالة المحمدية الإسلامية الخاتمة بقى فيه إمهال للأمم إلى يوم القيامة.. \nفربنا منع عننا كل حاجة ممكن تؤدي لأخطاء الأمم السابقة، بكل الزواجر والحدود والاحترازات الممكنة واللي بتشدد على أبواب المعاصي والآثام بإحكام، \nعندنا مثلا في شريعة الإسلام بناء التماثيل حرام،\n بعكس مثلا أيام قوم نوح كان عندهم حلال لكن بعد كده اتخذوها أصنام، \nالخمرة مثلا ماكانتش محرمة تحريم كامل في الشرائع السابقة كان مباح منها القليل الذي لا يُسكِر، \nبعكس الإسلام :\n\"ما كان كثيره مُسكر فقليله حرام\" \nوكذلك مقدمات الشذوذ كلها من تخنث وتشبه وغيره محرم، لإن كل ده بداية لإنبات بذرة فاحشة الشذوذ، \nوإللي ممكن شجرتها الخبيثة تثمر بعد أجيال لاحقة حتى مش لازم نشوف ثمرتها في نفس الجيل على فكرة، \nفلازم ناخد بالنا ومنقعش في البدايات، عشان المقدمات بتؤدي دايما للنهايات الحتمية، \nوإحنا قلنا إن الشيطان نَفَسُه طويل\n عادي ممكن يزرع البذرة النهاردة  ويحصدها بعد 100 سنة، \nهو احنا كنا نسمع زمان من تلاتين سنة مثلا إن في مسلمين شاذين والعياذ بالله \nلأ...بس بنسمع دلوقتي عن ده بل بنسمع عنه بأعداد كبيرة كمان للأسف،\nطب ليه\nبسبب التهاون في موضوع التشبه ومقدمات المرحمات وذرائعها\nفخدوا بالكم.. \n مش عشانكم انتم بس ... \nده عشان عيالكم كمان وعيالهم في الأجيال القادمة\n \nودي كانت نهاية من انتكست فطرته وكفر بالله، فإن الله يمهل ولكنه لا يهمل سبحانه\n☆آخر سؤال بقى،\n مش احنا قولنا إن كل قوم بيجيلهم نبي أو رسول منهم؟ طيب ماهو لوط مكنش منهم من الأول فطبيعي إنهم ميسمعوش كلام\nطيب يا جماعة هو ليه ربنا أصلا بيرسل النبي من نفس قومه؟\nمش عشان يكونوا عارفينه وعارفين صدقه وأخلاقه من طول السنين إللي عاشها معاهم؟ \nطيب لوط عليه السلام لما آمن لإبراهيم وخرجوا كلهم من العراق لأرض الشام كانوا لسه صغيرين في السن،\nفلوط عليه السلام لما انتقل لسدوم وعاش فيهم وتزوج منهم كانوا ناس عاديين جدا مكنوش وقعوا في الفاحشة،\nفخلال السنين دي كلها بقوا عارفين لوط عليه السلام كويس،\nفهنا تحقق الهدف وهو بيان صدق ومكانة لوط عليه السلام،\nبعد ما عاش معاهم سنين طويلة جدا،\nواحنا قلنا إن إبراهيم عليه السلام كان شيخ كبير في السن،\nفتخيلوا السنين إللي عاشها معاهم أد إيه،\nفلما بقى وقعوا في الفاحشة بالتدريج زي ما قلنا وكفروا بالله ووقعوا في باقي الموبقات ربنا أرسل لهم لوط إللي بقى واحد منهم وعارفينه خلال السنين دي كلها،\nعشان كده ربنا لما اتكلم عن سدوم، قال:《 قوم لوط》 وقال:\n 《قومه》 فده معناه إنه خلاص بقى واحد منهم وهم نفسهم معترفين بكده ومحدش أنكر على لوط إنه جاي من برة مدينتهم\nإبراهيم عليه السلام إللي كان في فلسطين ساعتها جاءه أمر تاني من الله عز وجل،\nيا ترى إيه الأمر ده وهل سيستجيب إسماعيل عليه السلام ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 15, "l": "الجزء ١٦ و ١٧ | إبراهيم ٦ و ٧", "u": "https://www.facebook.com/groups/710210019782034/permalink/725986744871028/", "t": "#قصص_الأنبياء\n#الحلقة_السادسة_عشرة\n#قصة_إبراهيم(٦)\n#قصة_الكعبة_على_مر_الزمن\nبعد ما جاءت البشرى لإبراهيم عليه السلام بولادة ابنه إسحاق، عدت فترة من الزمن وبعدين ربنا أمر إبراهيم عليه السلام بأمر جديد، \nذهب إبراهيم عليه السلام عشان يزور إسماعيل عليه السلام فلما راح له مكة لقاه كان قاعد عند شجرة في محيط البيت الحرام، وكان قاعد بيبريك نَبْل... \nعارفينه\n زي خشبة كده عمال بيبريها بسكين زي ما بنبري القلم الرصاص كده. \nفلما شافه إسماعيل عليه السلام قام له.. \nوإنتم عارفين لما الأب ولاّ الإبن بيشوفوا بعض بعد زمن بيعملوا إيه، وخصوصا لو كانت علاقتهم زي علاقة إبراهيم وإسماعيل عليهما السلام\nبعد ما سلموا على بعض، إبراهيم عليه السلام قال لإسماعيل إن ربنا أمره بأمر معين، فإسماعيل عليه السلام قال له: طبعا نفذ إللي ربنا يؤمرك بيه يا أبي، \nيعني كأنه بيقول له لو في ذبح تاني أنا معنديش مانع خالص عليه السلام\n \nفإبراهيم عليه السلام قاله طيب هتساعدني؟ \nقاله طبعا أساعدك\n \nفقاله ربنا أمرني إني أبني في المكان ده بيت \n وشاور على منطقة مرتفعة عن الأرض مغطياها الرمال، \nوكان ربنا هو إللي عرف إبراهيم المكان إللي هيبني فيه بالضبط، يُقال عن طريق ريح ربنا أرسلها فكنست المكان المقصود من الرمل ،ويُقال عن طريق سحابة وقفت في مكان البيت وظللت مساحة معينة كانت هي دي المساحة بتاعة الكعبة، \n\"وَإِذْ ((بَوَّأْنَا)) لِإِبْرَاهِيمَ ((مَكَانَ)) الْبَيْتِ أَنْ لَا تُشْرِكْ بِي شَيْئًا وَطَهِّرْ بَيْتِيَ لِلطَّائِفِينَ وَالْقَائِمِينَ وَالرُّكَّعِ السُّجُودِ\" \nوفوق الكعبة بالظبط البيت المعمور، وهو كعبة أهل السماء وموجود في السماء السابعة ، يدخله كل يوم سبعون ألف ملك يطوفون حوله لا يرجعون للطواف مرة تانية إلى يوم القيامة\n \nبدأ إبراهيم عليه السلام يبني البيت، \nفكان إسماعيل عليه السلام يأتي بالحجارة وإبراهيم عليه السلام هو إللي يبني، \nفقال إبراهيم عليه السلام لإسماعيل هات لي حجر أحطه في زاوية بحيث يكون علامة للناس يبدأوا من عنده الطواف، \nفجاء إليه جبريل عليه السلام بالحجر الأسود، وهو حجر من الجنة، وكان أول ما نزل الأرض.. \nو كان أشد بياضا من الثلج، ثم سوّدته خطايا بني آدم \n☆يعني سودته خطايا بني آدم وطاعات الموحدين لم تبيضه؟\n \nأيوة، لأن العادة إن الأسود هو إللي بيصبغ الأبيض وليس العكس، ولإن الذنوب عددها كبير جدا للأسف أكبر بكتير من الطاعات،\n\"وَإِن تُطِعْ أَكْثَرَ مَن فِي الْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ اللَّهِ\" \"ويعرفون نعمة الله ثم ينكرونها وأكثرهم الكافرون\"\n\"ولكن أكثرهم للحق كارهون\"\n \"وأكثرهم فاسقون\"\nوكمان فيه عبرة ...يعني الخطايا أثرت في الحجر الجامد الصلب فما بالنا بتأثير الذنوب في القلوب\n \nاستمر بناء الكعبة لحد ما ارتفع البنيان وبعدين إسماعيل جاب حجر عشان يقف عليه إبراهيم عليه السلام عشان يكمل البناء،\nوهم بيبنوا كانوا بيدعوا ربنا وبيقولوا : \n\"وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ \" \n☆وده يعلمنا إننا لما نعمل أي طاعة لله ندعي ربنا وإحنا بنعملها إنه يتقبلها مننا\n \nوكانت الكعبة هي أول بيت لله في الأرض. \nاستمر بناء الكعبة لحد ما ارتفع البنيان وبعدين إسماعيل جاب حجر عشان يقف عليه إبراهيم عليه السلام عشان يكمل البناء، وهم بيبنوا كانوا بيدعوا ربنا وبيقولوا :\n\"وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ \"\n☆وده يعلمنا إننا لما نعمل أي طاعة لله ندعي ربنا وإحنا بنعملها إنه يتقبلها منها\nوكانت الكعبة هي أول بيت لله في الأرض وبعد بنائها بأربعين سنة تم بناء المسجد الأقصى على يد يعقوب عليه السلام، \n\"إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكًا وَهُدًى لِلْعَالَمِينَ \" \nفي خلاف بين العلماء على مين إللي بنى البيت الحرام \n \nفي علماء قالوا إنهم الملائكة ... \nوفي فريق قال إن إللي بناها إبراهيم وإسماعيل ومعاهم أدلتهم، \nوفريق ثالث قال لأ ...ده القواعد -الأساس يعني- بتاع البيت الحرام موجود من أيام آدم عليه السلام، وإبراهيم وإسماعيل حفروا لحد ما وصلوا للقواعد وبنوا عليها وبردو معاهم أدلتهم، \nأنا شخصيا مقتنع بالرأي التالت الأخير ده، لإن إبراهيم عليه السلام قال: \n\"رَّبَّنَا إِنِّي أَسْكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيْرِ ذِي زَرْعٍ عِندَ بَيْتِكَ الْمُحَرَّمِ\" \nوالبيت مكنش لسه اتبنى\nوكمان ربنا قال : \n\"وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ\" \nيعني القواعد كانت موجودة من الأول وإبراهيم وإسماعيل عليهما السلام كملوا البناء عليها، \n☆في التعليقات هتلاقوا الرابط بتاع الأقوال والأدلة بتاعتهم لو حد عايز يعرف أكتر\n¤في هنا سؤال منطقي ومهم...مش الإسلام جه لهدم عبادة الأصنام إللي هي من الأحجار،\nطيب ماحنا لما بنسجد بيكون اتجاهنا لحجر أهه \nالأصل إننا بنطيع أمر ربنا...يعني احنا بنتجه في الصلاة للقبلة ناحية الكعبة إللي هي مصنوعة من حجر لأن ربنا هو إللي أمرنا بكده مش عشان ذات الكعبة، بدليل إننا لو ربنا أمرنا نتجه لمكان تاني كنا هنسمع ونطيع، \nفالعبرة باتباع أوامر ربنا مش في ذات الكعبة، يعني بنعبد ربنا مش الكعبة، \nفاحنا لما بنصلي بيكون اتجاه قلوبنا لله واتجاه أجسادنا للقبلة دإللي ربنا وجهنا ليها إللي هي الكعبة\n \n\"إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا\" \nولما كان عمر بن الخطاب رضي الله عنه بيطوف بالكعبة ويقبّل الحجر الأسود كان يقول:\nوالله إني لأعلم أنك حجر لا تضر ولا تنفع، ولولا إني رأيت رسول الله صلى الله عليه وسلم يقبِّلك ما قبّلتُك، \nفإحنا بنعمل كده لأننا مأمورين\nوفي نقطة كمان مهمة...في ناس بتبقى نفسها تروح تعمل عمرة مثلا وتقول عشان أتوب وأقرب من ربنا وكده وحزينة إنها مرحتش، \nويكون ربنا بحكمته وعلمه للغيب مانعهم رحمة بيهم لأن ممكن مثلا ذهابهم هناك يوقعهم في مخالفات توجب عليهم غضب ربنا وسخطه أو تكون مخالفة للأوْلى،\nزي السفر بدون محرم لو هي امرأة مثلا...أو محرمها مش راضي لسبب أو لآخر  فتعمل مشكلة عشان تروح....أو يحمل نفسه بالديون من الناس عشان يروح.. \nطيب ماهو ربنا إللي عند الكعبة هو ربنا إللي بتصليله الخمس صلوات ومعاكِ بعلمه وسمعه وبصره\nإللي عايز يتوب ويقرب من ربنا يعمل كده في أي وقت،\nفهل احنا بنبقى عايزين نروح لله فعلا ولا عشان نفسنا؟\nلو لله يبقى هنطيع ربنا كما يريد مش على مزاجنا،\nأيوة المكان له قدسيته وله روحانياته لكن ربنا مقلناش أبدا إني عشان أروح يبقى أعمل مخالفات وإلا فأنا كده بتعب نفسي في السكة الغلط وأنا مش واخدة بالي\nبعد ما تم بناء الكعبة ربنا أمر إبراهيم عليه السلام إنه يؤذن في الناس بالحج... \nويُروَى إن جبريل هو إللي علم إبراهيم عليه السلام صفة الحج إللي احنا عارفينها. \nفإبراهيم عليه السلام اتعجب وسأل: \nيارب طب هو أنا صوتي هيوصل للناس كلها إزاي\n \nفربنا قال له عليك الأذان وعلينا البلاغ، \nوفعلا أذّن إبراهيم عليه السلام بالحج فوصل صوته لكل أرجاء الأرض ووصل صوته لما في الأرحام وما في الأصلاب، \nوكل إنسان هيحج البيت إلى يوم القيامة بقدرة الله عز وجل فسبحان الله العظيم القدير\n \n☆وده يعلمنا درس\n \nوهو إننا مش بنطيع ربنا بشطارتنا ولا بندعو الناس بشطارتنا ده ربنا هو إللي بيوفقنا وبيوصل عننا يعني إحنا مجرد وسيلة، \nفلو محدش استجاب لأمرك بالمعروف ولا لنهيك عن المنكر فإنت عملت إللي عليك \nوده إللي ربنا هيحاسبك عليه \nما تقولوش هو أنا يعني إللي هغير الكون\n \nثم أنا هعمل إيه في وسط المنكرات دي كلها\n... \nاوعوا تقولوا كده، \nعلينا الأذان والبلاغ ، وعلى الله الهداية والإتيان بقلوب الناس\n \n(إنما أنت منذر..) \n(فإنما عليك البلاغ.)\nوبعد زمن إبراهيم عليه السلام ، \nكانت الكعبة بتتعرض للسيول فيقع منها جزء أو يأثر فيها عوامل الجو فكان إللي بيصحلوا فيها وواخدين بالهم منها ،قبيلتين اسمهم جُرهم والعماليق \nاتعرضت الكعبة لأكتر من محاولة للهدم، وكان أول واحد حاول يهدمها رجل اسمه \"تُبَّع أسعد\" ملك اليمن.. وكان مشرك لكنه آمن بالله و اتبع اليهودية ، \nوكان في قبيلة عايزة تنتقم منه فأغرته يهدم البيت الحرام عشان ياخد منه الكنوز المدفونة فيه، فكان معاه اتنين من علماء اليهود فسألهم.. فقالوا له: \nربنا هيهلكك لو قربت منه ، \nإحنا منعرفش بيت لله على الأرض إلا البيت ده، فإنت تطوف \nحواليه وتعظمه وبس.. إياك تمسه بسوء \nفقال لهم وانتم ليه ماتعملوش كده وتطوفوا حواليه انتوا كمان حواليه\n \nقالوا نفسنا نعمل،لكن أهل البيت ده ملوه بالأصنام وده شرك واحنا علماء مينفعش نطوف والأصنام موجودة\n. \nوفعلا عمل بكلامهم وعظم الكعبة وانصرف عن فكرة هدمها.. وكان هو أول واحد كسى الكعبة\n. \nوبعدها بسنين اتعرضت الكعبة لمحاولة هدم تانية وكانت على يد أبرهة الحبشي وكان جايب معاه فيل عشان يهدم الكعبة زي ما كلنا عارفين في القصة بتاعة الفيل وهدم الكعبة، \nوإن الفيل رفض يتحرك وربنا أرسل عليهم طيرا أبابيل -يعني طيور جماعات جماعات- فقذفتهم بحجارة من سجيل -يعني طين متحجر وصلب جدا-،\nفبقت الحجارة من دول تصيب المجرم منهم يقوم يتحول لعصف مأكول -يعني شبه ورق النبات اللي عضعضت الدواب منه حتت وسابته والعياذ بالله- \nوكانت الحادثة دي قبل مولد رسول الله الله صلى الله عليه وسلم بخمسين يوم على أرجح الأقوال \n \n☆يعني كفار قريش إللي حاربوا رسول الله صلى الله عليه وسلم بعدين ولم يؤمنوا برسالته كانوا شافوا المعجزة الإلهية دي قصاد عينهم عين اليقين.. ولكنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور\n \nبعد الحادثة دي بكم سنة اتعرضت الكعبة لسيل شديد خربها ،وبقت محتاجة إعمار وترميم \nفقال أهل مكة: إحنا محتاجين نرمم الكعبة ومحتاجبن فلوس للأمر ده، \nفقالوا نصلحها بالمال الحلال ، يعني ماندخلش فيها مال ربا، وماندخلش فيها مهر بغاء ،يعني فلوس من ارتكاب الفواحش، \n☆يعني كانوا عارفين يفرقوا أهو بين الحلال الطيب والخبيث المحرم\n \nفجمعوا الفلوس الحلال لقوها قليلة...ودي طبعا كانت مشكلة،\nوواجهتم مشكلة تانية هل يهدموا الكعبة ولا يسيبوها لكن يرمموها؟، \nفالوليد بن المغيرة قال نهدمها ونبنيها تاني ... \nلو بيت واحد فينا جراله حاجة هيهدمه ويبنيه تاني... فما بالكم ببيت الله! \nسبحان الله العظيم! \nتخيلوا إن الوليد ده هو صاحب القصة المشهورة في تكذيبه لرسول الله ﷺ والقصة موجودة في سورة المدثر إللي ربنا قال عنه فقُتل كيف قدر؟! \nقصته بالتفصيل هتلاقوها في السيرة النبوية،\nشايفين كان حريص جدا ازاي قبل بعثة النبي ﷺ على الكعبة بيت الله ويعلم يقينًا إن الله هو رب العالمين ومعبودهم الحق جميعا.. لكنه العمى والعناد والكفر \nهمم كلهم كانوا مؤمنين بوجود ربنا على فكرة ، بس كانوا مؤمنين بتوحيد الربوبية فقط.. إللي هو إن ربنا هو خالق السماوات والأرض والكون و و....و.... \nلكن مكنوش مؤمنين بتوحيد الألوهية إللي هو إن ربنا الخالق ده هو الله ، الوحيد المستحق للعبادة وإن الحكم له فقط \nالمهم لما قال نهدمها ونبنيها من الأول أهل مكة خافوا لأنهم شافوا إللي حصل لجيش أبرهة لما حاول يهدمها\n \nفقالوا للوليد بن المغيرة إنت صاحب الفكرة ابدأ ونشوف لو جرالك حاجة هنرممها بس... لكن لو محصلش حاجة هنكمل معاك\nوفعلا بدأ الوليد يهدم في الكعبة وهو بيقول يارب احنا بنهدمها عشان نبنيها تاني بس، وتمت الفكرة بنجاح وبدأوا يبنوها،\nوهما بيبنوها الفلوس قصّرت معاهم فبدل ما يعملوها ليها بابين باب للدخول وباب للخروج عملوا لها باب واحد، \nوسابوا جزء منها مش مبني ومش مكتمل مع بقية بناء الكعبة نتيجة لتعجبز الفلوس معاهم طبعا بسبب قلة المال الحلال زي ما قلنا،\n بس حطوا عند الجزء الغير مكتمل ده علامة عشان الناس تطوف من خارجها فتبقى لفة الطواف حوالين الكعبة كاملة مش ناقصة، فمحدش يلف في الجزء اللي مش مكتمل البناء يعني ويبقى طوافه ناقص.. \nالعلامة دي هي حِجر إسماعيل الحتة إللي عند الكعبة إللي عاملة زي القوس دي\n ) \nفالمفروض إن الجزء ده كان يدخل في الكعبة لكن عشان الفلوس ما كفتش فسابوها على كده، \nوباب الكعبة كان واصل للأرض قبل كده، \nلكن هما رفعوه عن الأرض وهما بيبنوها من تاني عشان يدخلوا الكعبة الناس إللي هم عايزينهم بس\n \nوبعد فتح مكة رسول الله صلى الله عليه وسلم قال لعائشة رضي الله عنها لولا إن أهل مكة لسه مسلمين جديد وممكن يتخضوا ويحصل قلق كنت هدمت الكعبة وبنيتها على قواعد إبراهيم ، يعني زي ما إبراهيم عليه السلام بناها، بناء مكتمل الجدران والعمارة،\nعدت سنين واعتدى أهل الشام على الحرم وحرقوا الكعبة. \nفعبد الله بن الزبير رضي الله عنه -وكان خليفة ساعتها- استشار الناس واستخار ثلاثة أيام إنه يهدم الكعبة ويبنيها زي ما كان رسول الله ﷺ عايز،\nوفعلا هدمها وبناها على قواعد إبراهيم.. \nبعد ما تولى عبد الملك بن مروان رضي الله عنه الخلافة وشاف الكعبة متغيرة ومكنش يعرف الحديث بتاع رسول الله ﷺ  أمر الحجاج بن يوسف الثقفي إنه يهدمها ويرجعها زي ما كانت، \nوبعد ماهدمها وبناها تاني واحد من الصحابة قال لعبد الملك بن مروان الحديث بتاع رسول الله  ﷺ فقال عبد الملك ياريتنا كنا سيبناها زي ماهي.. \nلكنه مع ذلك ما رجعهاش تاني زي ما كانت في عهد الزبير.. \nفي زمن المهدي بن المنصور استشار ابن المنصور الإمام مالك ابن أنس إنه يهدم الكعبة ويعيد بنائها مرة تانية زي ماكان بناها عبد الله بن الزبير فقال الإمام مالك :أخاف إن الخلفاء ياخدوها لعبة \n \nكل شوية حد ييجي يهد عمارة الكعبة اللي قبل منه ويختلف الناس لفريقين واحد ياخد برأي ابن الزبير والتاني ياخد برأي بن مروان وكل واحد يهدم ويبني! \nفاقتنع ابن المنصور بكلام الإمام مالك وفضلت الكعبة زي ماهي إلى يومنا هذا.. \nمن الأحداث إللي مرت على الكعبة هي هجوم القرامطة على الكعبة وقتلهم للحجيج وسرقتهم للحجر الأسود . \nوفضل عندهم ٢٢ سنة ،لحد ما المسلمين استعادوه بعد كده. \nوبأمر الله هتفضل الكعبة موجوة لحد آخر الزمان بعد موت عيسى عليه السلام لحد ما ييجي واحد من الحبشة يُقال له \"ذو السويقتين\" ويهدمها حجر حجر في زمن لا يقال في الأرض كلمة ((الله)) زمن شرور وفساد عظيم.. نسأل الله ألا نكون فيه، \nوبعدين تقوم الساعة بعدها بفترة قليلة على شرار الخلق ونسأل الله تعالي ألا نكون معهم\n \nمن المعلومات القيمة : \nإن مفيش اي طيارة بتعدي من فوق الكعبة وده لإن منطقة الحرم محرَّمة لغير المسلمين، فالطائرات بيكون فيها من جميع الجنسيات فمينفعش يعدوا على منطقة الحرم \n \nدي كانت أهم الأحداث إللي مرت على الكعبة المشرفة،\nأنا حاولت أقولكم المختصر المفيد لأن كل نقطة فيها أحداث كتير ومحتاجة شرح\nوإن شاء الله الجزء الجاي هيكون آخر جزء في قصة إبراهيم وإسماعيل عليهما عشان نكمل باقي قصص الأنبياء\n#قصص_الأنبياء\n#الحلقة_السابعة_عشرة\n#قصة_إبرهيم(٧)\n#الجزء_الأخير\nبعد ما إبراهيم عليه السلام بنى الكعبة مع إسماعيل عليه السلام رجع إلى فلسطين لزوجته سارة وكانت قد ولدت إسحاق عليه السلام،\nفي يوم من الأيام طلب إبراهيم عليه السلام من ربنا طلب،\nقاله يارب أَرِني كيف تحيي الموتى، فربنا سأله:\nأَوَلم تُؤمن؟\nيعني مش انت خلاص آمنت بي،\nفإبراهيم عليه السلام قال: طبعا مؤمن ...بس عايز قلبي يبقى مطمن.\n\"وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِي\"\n☆يعني إيه الكلام ده\nفي حاجة اسمها علم اليقين وحاجة تانية اسمها عين اليقين\nعلم اليقين يعني أكون عاااارف ومتأكد مثلا إن الجنة والنار حق، وإن ربنا هو إللي خلقنا وخلق الكون،\nزي عمر بن الخطاب رضي الله عنه لما قال: لو شفت الجنة والنار حالا وأنا في الدنيا إيماني مش هيزيد حاجة، لأنه متأكد من وجودها\nعين اليقين بقى إن الإنسان يشوف بعينه \nيعني إحنا مؤمنين بالصراط وبالميزان وبعلامات يوم القيامة،\nلما نشوفها يبقى إحنا انتقلنا من مرحلة علم اليقين لعين اليقين\nوهو ده إللي إبراهيم عليه السلام طلبه من ربنا...هو عنده علم يقين إن ربنا هو إللي بيميت ويُحيِي ...لكن عايز ينتقل لمرحلة أعظم وهي عين اليقين إنه يشوف بعينيه...فاهمين\nعارفين زي إيه مثلا\nلما تكون عايز تعمل حاجة معينة وتطلب من ربنا إنه يديك علامة كده إن الحاجة دي كويسة،\nيعني لو بتقدم على وظيفة وانت عايزها مثلا..أو عايز تدخل كلية معينة وإنت عارف إنها مناسبة ليك بس بتكون عايز حاجة كده تطمنك،\nأهه ده تقريبا الإحساس إللي كان عايزه إبراهيم عليه السلام ،\nهو كان موقن بقدرة ربنا على إحياء الموتى بدليل إنه قال: 《أرني كيف》 يعني سأل عن الكيفية مش عن الإحياء نفسه\nفهو لم يشك لحظة على قدرة ربنا في إحياء الموتى....بس هو حب يشوف بعينه كمان ...يعني بطبيعة البشر إللي بيكونوا عايزين يشوفوا حاجة اتحكى لهم عنها،\nيعني مش ساعات حد ييجي يحكيلك على حاجة هتحصل زي حفلة مثلا أو زفاف أو مثلا جالك خبر ثقة برجوع حد من حبايبك من السفر...أو... أو.. \nمش انت بتكون متشوق ونفسك تشوف ده بعينك دلوقتي حالا عشان تطمن اكتر\nأهه ده نفس الموضوع تقريبا\nفربنا استجاب لطلبه وقال له: خذ أربعة طيور واذبحهم وقطعهم واخلطهم على بعض وبعدين وزع الخليط ده على كذا جبل بحيث كل جبل يكون عليه جزء...\nعايزاكم تتخيلوا كده معايا ...أربعة فرخات مثلا مذبوحين قصادك قطعتهم وخلطتهم وحطتهم في كيس ...تعرف تطلع أنهو جزء بتاع أنهي فرخة \nمستحيل طبعا\nبعد ما إبراهيم عليه السلام نفّذ كل ده،\nربنا قال له : نادي عليهم هتلاقيهم جايين ليك.\n\"قَالَ فَخُذْ أَرْبَعَةً مِّنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ اجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ادْعُهُنَّ يَأْتِينَكَ سَعْيًا\"\nوبكده شاف إبراهيم عليه السلام معجزة إحياء الموتى أمامه\nدين إبراهيم عليه السلام ودين كل الأنبياء هو الإسلام،\n\"إِنَّ الدِّينَ عِندَ اللَّهِ الْإِسْلَامُ\"\nوالإسلام معناه الإستسلام لأوامر لله، وتوحيد الله بالعبادة،\nممكن الشرائع تختلف إللي هي الحلال والحرام ...\nيعني يكون عندنا حاجات حرام كانت حلال في الشرائع إللي قبلنا،\nلكن عموميات الحرام واحدة تقريبا زي تحريم القتل والسرقة والكذب والظلم...الخ\nفاللي بيختلف بيكون بعض التشريعات من زمن لزمن،\nإنما الأصل واحد وهو توحيد الله بالعبادة ،\nحتى في اليهودية والنصرانية...لكن أهل الكتاب حرفوا العقيدة زي ما هنقول إن شاء الله لما يبجي وقتها\nنرجع لإبراهيم عليه السلام، \nكان إبراهيم عليه السلام يدعو إلى الله في منطقة فلسطين وما حولها ويعلم الناس الدين،\nوزي ما أُنزل على محمد ﷺ القرآن،\nأُنزل على إبراهيم عليه السلام الصّحُف،\nوكانت عبارة عن مواعظ وحِكم وعِبر، وأُنزلت عليه في أول ليلة من ليال رمضان،\nوإبراهيم عليه السلام كان هو أول من اخْتَتَن وكان عمره ثمانين عام،\nيُقال أن إبراهيم عليه السلام عاش مئتي سنة وفي قول إنه عاش ١٦٠ سنة، وكان قد تزوج بعد موت سارة وأنجب ٦ أبناء،\nفيكون مجموع أبناء إبراهيم عليه السلام مع إسماعيل وإسحاق عليهما السلام ثمانية أبناء،\nواحنا منعرفش حاجة عن باقي أبناء إبراهيم عليه السلام،\nنعرف فقط عن إسماعيل وإسحاق،\nربنا جعل في ذرية إبراهيم عليه السلام النبوة والرسالة...\nإسماعيل عليه السلام هيكون في ذريته محمد ﷺ \nوإسحاق عليه السلام هيكون في ذريته باقي الأنبياء....يعقوب ويوسف وداود وسليمان وأيوب ويونس و....و... \nومات إبراهيم عليه السلام ودُفن في مدينة الخليل المعروفة اليوم، في مغارة كان اشتراها ودفن فيها زوجته سارة،\nوإللي تولى دفنه هو إسحاق وإسماعيل عليهما السلام.\nكان إسماعيل عليه السلام رسول لقبيلة جُرهم إللي اتكلمنا عنها قبل كده وقلنا إنها جت سكنت عند الكعبة لما تفجر ماء زمزم،\nوكان رسول لقبيلة 《العَمَاليق》 إللي كانوا بأرض الحجاز،\nفي منهم من آمن ومنهم من كفر،\nوقلنا إن إسماعيل عليه السلام كان تزوج من قبيلة جُرهم\nفكان يجلس في مكة حتى بعد موت أمه هاجر عشان بيدعو الناس في منطقة مكة والبلاد المحيطة بيهم ويشرح لهم تعاليم الدين \nوكان أبناء إسماعيل عليه السلام والناس إللي أسلموا معاه هم المسؤولين عن خدمة الحجيج،\nوكان من صفات إسماعيل عليه السلام إنه كان صادق الوعد ...يعني لا يخلف وعد قطعه أبدا...\nحتى يُذكر عنه إن في واحد إداله ميعاد فإسماعيل عليه السلام فضل مستنيه والراجل نسي ...وافتكر بالليل فراح لإسماعيل لقاه لسه مستنيه\n \nمن شدة ماهو حريص على الوفاء بالوعد\n\"وَاذْكُرْ فِي الْكِتَابِ إِسْمَاعِيلَ ۚ إِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا\"\n☆وإحنا كمسلمين مأمورين بصدق الوعد...فلما توعد حد بحاجة لازم توفي بوعدك ده،\nلأن خلف الوعد من صفات المنافقين، إديت ميعاد يبقى تكون حريص إنك تكون موجود في الوقت \nوعدت إبنك أو أخوك أو أي حد إنك هتعمل له حاجة يبقى لاااازم توفي بوعدك وإلا متوعدش من الأول\nوكان عليه السلام حريص على تذكير أهله بالصلاة والزكاة وطاعة ربنا،\n\"وَكَانَ يَأْمُرُ أَهْلَهُ بِالصَّلَاةِ وَالزَّكَاةِ وَكَانَ عِندَ رَبِّهِ مَرْضِيًّا \"\nلأن طبيعة الإنسان إن أكثر حد هيحب لهم الخير هم أهله،\nوهو في خير أعظم من إن الإنسان يجتمع مع إللي بيحبه يوم القيامة في الجنة بعيدا عن غضب الرحمن\nإتولد لإسماعيل عليه السلام ١٢ ولد وانتشرت ذريته في مكة وما حولها، وإسماعيل عليه السلام هو أبو العرب المستعربة،\nلأنه أول من نطق بالعربية الفصحى إللي إحنا عارفينها بعد ما كان بيتكلم السريانية زي إبراهيم عليه السلام.\n☆والعرب بينقسموا لثلاثة أقسام :\n◇أول قسم :\nعرب بائدة: يعني خلاص انتهوا ومبقوش لهم أثر قبل ما ييجي الإسلام، زي قوم عاد وثمود،\n◇ثاني قسم: \nالعرب العاربة: ودول اسمهم القَحْطَانِيين يرجع نسبهم لواحد من أبناء سام بن نوح عليه السلام.\n◇القسم الأخير بقى وإللي يهمنا هو: \nالعرب المُسْتَعرِبة:\nودول كل العرب إللي جاءوا من نسل إسماعيل عليه السلام\nوإللي بيتكلموا اللغة العربية الفصحى إللي هي لغة القرآن إللي احنا عارفينها\nأما اللغة العربية إللي قبل كده فهي كانت قريبة من اللغة العربية إللي احنا عارفينها لكن لهجاتها مختلفة،\nيعني كمثال تقريبا كده زي اختلاف لهجات الدول العربية دلوقتي \nمات إسماعيل عليه السلام وعنده ١٣٠ عام كما يُقال،\nومحدش يعرف مكان دفنه فين ، في ناس بتقول إنه مدفون في الحِجر، لكن مفيش دليل على كده حتى العلماء في العصر الحديث بينفوا دفن إسماعيل عليه السلام في منطقة الحِجر.\nإن شاء الله المرة الجاية نتكلم عن النبي الثالث من الأنبياء العرب وقصته مع قومه"}, {"n": 16, "l": "الجزء ١٨ و١٩ | شعيب | يوسف ١ | إسحاق ويعقوب", "u": "https://www.facebook.com/groups/710210019782034/permalink/726780254791677/", "t": "#قصص_الأنبياء\n#الحلقة_الثامنة_عشرة\n#قصة_شعيب\nبعد هلاك قوم لوط إللي تكلمنا عليهم قبل كده؛ بعد كم سنة في مكان قريب منهم كان في قبيلة اسمها مَديَن، أهل مدين دول كانوا ناس كفار بيعبدوا شجرة اسمها الأَيْكة،\nوكانوا من أسوأ الناس معاملة \nلما يكونوا بيبيعوا حاجة بيُقللوا الميزان لمصلتحهم،\nأو يبيعوا مثلا القماش ناقص بفلوس زيادة، يعني يبيعوا ٩٠سم قماش بسعر متر، \nلكن لما هم إللي يشتروا  بياخدوا زيادة عن حقهم ...يعني ياخدوا بالزيادة ويدفعوا بالناقص.\n☆ولو بصينا في حياتنا هنلاقي ناس كتير بتعمل كده إلا من رحم الله، \nلما تيجي تشتري حاجة تلاقيها عمالة تفاصل وتفاصل لحد ما تبخس ثمن الحاجة وتجيبها الأرض\nلكن تعالوا شوفوهم لما يكون فيها مصلحتهم تلاقيهم بيزودوا السعر ويحلفوا بالله كذب عادي جدا إن الحاجة دي سعرها كده\nودول اللي ربنا قال عنهم في القرآن \"المُطَفّفِين\" وتوعّدهم بالويل والعياذ بالله\nوكان أهل مدين قطّاعين طُرق...بيطلعوا على الطريق ويخوّفوا المسافرين وياخدوا أموالهم وحاجتهم، كانو بأفعالهم أشبه بقوم لوط،\nفلأن ربنا رحيم ومش بيعذب حد ولا يُهلكه إلا لما يبعتله حد يُذكره ويُوعظه ويُنبهه، ربنا أرسل لهم واحد منهم اسمه شعيب.\n\"وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا\"\nشعيب عليه السلام كان زيه زي باقي الأنبياء لم يعبد صنم أبدا ولم يكفر بالله أبدا...كلهم على الفطرة...\nيعني كل إنسان ربنا بيخلقه بيكون على فطرة الإسلام والتوحيد، \nوبعدين بقى يبدأ التغيير فيه من إللي حواليه وخصوصا الأب والأم إللي ليهم التأثير الأكبر على عقيدة الطفل،\nفالأنبياء والرسل ربنا حفظهم بفطرتهم لحد ما تجيلهم الرسالة\nفربنا أوحى لشعيب عليه السلام إنه هيكون رسول لقومه عن طريق جبريل فجبريل عليه السلام هو المَلك المسؤول عن تبليغ الوحي للأنبياء،\nويُقال إن شعيب عليه السلام من ذرية إبراهيم عليه السلام لكن مفيش دليل على كده،\n وخصوصا إن شعيب عليه السلام من الأنبياء العرب العاربة إللي رسول الله ﷺ  ذكرهم في الحديث، إن الأنبياء العرب أربعة، وإبراهيم عليه السلام مكنش عربي وأول عربي مُستعرِب هو إسماعيل عليه السلام\nعالعموم نسبه مش هيفيدنا بشيء.. لأنه لو كان هيفيدنا كان ربنا قالنا سواء في القرآن أو في السنة،\nفربنا دايما بيقولنا على الحاجات إللي هتنبني عليها حاجة مفيدة لينا،\nلكن الحاجة إللي مش هتفيدنا مش بيذكرها زي مثلا مرات إبليس اسمها إيه ولّا هو متزوج أصلا ولّا لأ\nفاللي يهمنا إن شعيب عليه السلام نبي مرسل لقوم مدين إللي كانوا قريبين من مكان وزمان قوم لوط،\n\"وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا \"\nأول حاجة دعاهم ليها كعادة الأنبياء زي ما قبل كده\nهي:\nإنهم يعبدوا الله وحده...ربنا إللي خلقهم وبيرزقهم وبيشفيهم إذا مرضوا ملوش شريك ولا له ولد هو الخالق الوحيد للكون ده،\nونصحهم إنهم يوفوا المكيال ويرجعوا للناس أموالهم، وميخدوش زيادة عن حقهم ...ورزق ربنا أحسن لهم من إنهم ياخدوا أموال الناس بالباطل.\n\"قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ قَدْ جَاءتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءهُمْ ولاَ تَعْثَوْا في الأرضِ مُفْسِدِين\"\nربنا إللي بيرزق و بيبارك في الأموال، لو انتم مشيتم في طريق غلط لجمع الأموال دي ربنا مش هيبارك وهتفتقروا،\nفالحلال فيه بركة حتى لو كان قليل، والحرام هيفنى سريعا ويَمحقُه الله حتى لو كان كثير،\n\"بَقِيَّةُ اللَّهِ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ وَمَا أَنَا عَلَيْكُمْ بِحَفِيظٍ\"\nوأنا بعمل إللي بقولكم عليه...مش بقولكم على الحاجة وأعمل عكسها، أنا كل إللي عايزه هو الإصلاح على أد ما أقدر وأعمل إللي عليّ والتوفيق من عند ربنا.\n\"وَمَا أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَى مَا أَنْهَاكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا الْإِصْلَاحَ مَا اسْتَطَعْتُ وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ\"\n☆ودي الدعوة إلى الله بالقدوة\nلما تحب تدعي حد حاول تكون قدوة في إللي بتدعي ليه الناس على أد ما تقدر لأن ده بيكون أكثر تأثيراً في قلوب الناس،\nبتدعي الناس للصدق كُن صادق...بتدعي الناس لمساعدة الغير إنت كمان ساعد غيرك وهكذا،\nلكن مش معنى كده إننا نسيب الدعوة بحجة إننا مش بعمل إللي بنقوله أو لأننا أصحاب ذنوب\nكلنا مش معصومين وأكيد بنقع في أخطاء وتقصير وزلات\nبس بنجاهد نفسنا إننا نعمل إللي بندعي الناس بيه، فمتوقفش دعوة الناس للخير مهما كنت على ذنوب، أو بتتعرض لعثرات في طاعتك،\nلعل ببركة دعوتك دي ربنا يرزقك العمل بيها في يوم من الأيام\nالمهم، قوم شعيب قالوا له:\nهي الصلاة إللي إنت بتصليها هي إللي أمَرِتك إننا نسيب عبادة الأَيْكة إللي كان بيعبدها آباؤنا أو نعمل في فلوسنا إللي إحنا عايزينه \nده إيه الصبر والبصيرة إللي إنت فيها دي\nاحنا كنا عارفينك أعقل وأَرشد من كده\n\"قَالُوا يَاشُعَيْبُ أَصَلَاتُكَ تَأْمُرُكَ أَنْ نَتْرُكَ مَا يَعْبُدُ آبَاؤُنَا أَوْ أَنْ نَفْعَلَ فِي أَمْوَالِنَا مَا نَشَاءُ إِنَّكَ لَأَنْتَ الْحَلِيمُ الرَّشِيدُ \"\nفقال لهم :\nافتكروا نعمة ربنا عليكم وإزاي كنتم مجموعة صغيرة وربنا زوّد في عددكم، اتقوا ربنا إللي خلقكم أنتم وآباؤكم، واستغفروا ربنا وتوبوا ده ربنا رحيم وودود وبيقبل التوبة\n\"وَاذْكُرُوا إِذْ كُنْتُمْ قَلِيلًا فَكَثَّرَكُمْ\"\n\"وَاسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ\"\nفقالوا له:\nإنت شكلك اتسحرت\n\"قَالُوا إِنَّمَا أَنْتَ مِنَ الْمُسَحَّرِينَ\"\nفقال لهم:\nطيب أنا وريتكم معجزة من ربكم تثبت لكم إني نبي من عند ربنا وتطمنكم، وتأكد لكم إني مش بتكلم من نفسي، فاسمعوا الكلام بقى\n\"قَدْ جَاءتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ\"\n☆ملحوظة: \nمفيش أي دليل من القرآن أو السنة عن إيه هي تحديدا معجزة شعيب عليه السلام، فمفيش داعي للكلام فيها بكلام لا ينبني عليه عمل زي ما قلنا\nفقال له قومه:\nإحنا مش حابين كلامك ده ولا عايزين نسمعه ومش فاهمين إنت بتقول إيه أساسا \nوإنت ضعيف أصلا ولولا عيلتك كنا حدفناك بالطوب لحد ما نقتلك لإن انت شخصيا مش عزيز علينا في شيء ولا غالي علينا يعني\n\"قَالُوا يَاشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِمَّا تَقُولُ وَإِنَّا لَنَرَاكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَاكَ وَمَا أَنْتَ عَلَيْنَا بِعَزِيزٍ \"\nعلى فكرة شعيب عليه السلام يُسمى خطيب الأنبياء بسبب فصحاته وحُسْن كلامه...ودول بيقولوا احنا مش فاهمين إنت بتقول إيه\nوطبعا مفيش جديد\n هي دي عادة المُعاندين المتكبرين في كل زمان، من ظلم وبهتان وسخرية واستهانة وغرور وتجبر وكتمان للحق والعياذ بالله،\nفرد عليهم وقال: \nبقى معقولة عيلتي أعز عندكم من ربنا\n \nبقى بتراعوني عشان خايفين من عيلتي ومش خايفين من ربنا إنكم بتؤذوا رسوله إللي جايلكم ببرهان مُبين من عنده عز وجل\n\"قَالَ يَاقَوْمِ أَرَهْطِي أَعَزُّ عَلَيْكُمْ مِنَ اللَّهِ وَاتَّخَذْتُمُوهُ وَرَاءكُمْ ظِهْرِيًّا إِنَّ رَبِّي بِمَا تَعْمَلُونَ مُحِيطٌ\"\nطيب....\nاصبروا بقى لحد ما ربنا هو إللي يحكم بيني أنا وإللي آمنوا معايا وبينكم.\n\"وَإِنْ كَانَ طَائِفَةٌ مِنْكُمْ آمَنُوا بِالَّذِي أُرْسِلْتُ بِهِ وَطَائِفَةٌ لَمْ يُؤْمِنُوا فَاصْبِرُوا حَتَّى يَحْكُمَ اللَّهُ بَيْنَنَا وَهُوَ خَيْرُ الْحَاكِمِينَ\"\nفقالوا له بكل كِبر:\nيا إما نطردك برة البلد إنت وإللي اتبعوك دول أو ترجعوا عن إللي في دماغكم ده وتكونوا على دينا \n\"قَالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِنْ قَوْمِهِ لَنُخْرِجَنَّكَ يَاشُعَيْبُ وَالَّذِينَ آمَنُوا مَعَكَ مِنْ قَرْيَتِنَا أَوْ لَتَعُودُنَّ فِي مِلَّتِنَا\"\nقال لهم: حتى لو إحنا مش عايزين\nمحدش أبدا هيرجع للكفر بعد ما ذاق حلاوة الإيمان بالله إلا وهو مُكره، \nده احنا لو رجعنا عن الحق إللي ربنا هدانا ليه يبقى بننكر إنه حق وبنفتري على ربنا الكذب ...عايزينا نرجع بعد ما ربنا نجانا من الضلال ده\n\"قَالَ أَوَلَوْ كُنَّا كَارِهِينَ قَدِ افْتَرَيْنَا عَلَى اللَّهِ كَذِبًا إِنْ عُدْنَا فِي مِلَّتِكُمْ بَعْدَ إِذْ نَجَّانَا اللَّهُ مِنْهَا\"\nإحنا مش هنرجع أبدا إلا لو ربنا أراد حاجة تانية هو ملجأنا \nوهو إللي هينصرنا  \n\"وَمَا يَكُونُ لَنَا أَنْ نَعُودَ فِيهَا إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَيْءٍ عِلْمًا عَلَى اللَّهِ تَوَكَّلْنَا \"\n☆ده إيه التسلط بتاع قوم شعيب ده\n يا تبقى معايا وعلى مزاجي يا إما هطردك وهأذيك وهعذبك...مفيش حرية اختيار خالص\nوده بنشوفه في حياتنا على فكرة كتير وممكن نكون بنعمله من غير ما ناخد بالنا،\nيعني مثلا لو صاحبك مش عايز يعمل حاجة معينة أو يقول رأي مخالف لرأيك فبدل ما تحترم رغبته تقوم معصب عليه وممكن تتخانق معاه وممكن تقاطعه \nوحتى ساعات الأم والأب مع عيالهم، ده العيال ممكن يكون رأيهم صح عن الأب والأم ومع ذلك يمشوا كلامهم بحجة إنهم خايفين لهيبتهم تقع قصاد عيالهم \n \nإللي هو: إزاي يعني حتة عيل يمشي كلامه علينا\nوطبعا ده كِتمان للحق وقبول للباطل وتكبر عن الاعتراف بصواب رأي إللي قدامي لما يكون على حساب نفسي، فبالتالي بيكون في ده شيء من التعريفين بتوع الكبر،\n إللي النبي ﷺ عَرَّفُه وقال: \n\"الكبرُ هو بَطَرُ الحق وغَمطُ الناس\" \nيعني كتمان الحق واحتقار الناس.. واتكلمنا عنه بالتفصيل في الجزء الأخير من قصة نوح لو تفتكروا،\nوحتى في الجروبات على الفيس أو الواتس...\nمثلا تلاقي واحد أو واحدة منزلة بوست بتسأل عن أي حاجة عااادية جدا تلاقي إللي يدخل يعلق ويقول متتكلموش في المواضيع دي،\nويبدوأ يتكلموا عن الجروب أو إللي منزل المنشور\nأيوة نعم يعني حضرتك عايز إيه \nمش عاجبك الموضوع خلاص عديه محدش ألزمك بحاجة فمتلزمش الناس برأيك،\nكل واحد حُر يعبر عن رأيه ومواضيعه إللي حابب يتكلم فيها أو يسأل عنها وتخُص اهتماماته ، طبعا بشرط\nإن الموضوع ميكونش فيه حاجة مخالفة للشرع أو حد بيُحرم حلال أو بيحلل حرام وبيتكلم بغير علم\nهنا بقى لازم تتكلم ولو كره الكارهون\nغير كده خلاص، خلونا نتعلم إزاي نحترم آراء بعض ورغبات بعض \nقوم شعيب عليه السلام بقى قعدوا يقولوا للمؤمنين لو مشيتم ورا شعيب هتخسروا ...مش هتلاقوا فلوس\n\"وَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ لَئِنِ اتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَخَاسِرُونَ \"\nفشعيب عليه السلام بدأ يخوّفهم ويقولهم متخلوش كرهكم لي أو لكلامي يخليكم متتبعوش الحق، \nلو أسلوبي مش عاجبكم وشايفين إني ضعيف وإن فيه أفصحُ مني لسانًا وأَبْيَنُ كلامَا واني لا أستحق النبوة والرسالة إللي ربنا أنزلها عليّ اتبعوا الحق وملكوش دعوة بناقل الحق،\nربنا هيسألكم عن الحق إللي جالكم...\nمش هتقدروا تقولوا ساعتها أصل أسلوبه كان وحش...\nأو تقولوا إشمعنى هو إللي يقولنا كده وهو ضعيف.\nيا جماعة اتعظوا باللي حصل قبل كده،\nقوم نوح وقوم هود وقوم صالح قالوا نفس كلامكم ...وكانت نهايتهم إيه؟...ونهاية قوم لوط بالذات مش بعيدة عنكم\n\"وَيَا قَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِي أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَالِحٍ وَمَا قَوْمُ لُوطٍ مِنْكُمْ بِبَعِيدٍ \"\nفقالوا له: بص إنت بشر زينا وإحنا شايفينك كذاب \n\"وَمَا أَنْتَ إِلَّا بَشَرٌ مِثْلُنَا وَإِنْ نَظُنُّكَ لَمِنَ الْكَاذِبِينَ \"\nلو إنت فعلا صادق هات العذاب إللي إنت بتقول عليه ده\n\"فَأَسْقِطْ عَلَيْنَا كِسَفًا مِنَ السَّمَاءِ إِنْ كُنْتَ مِنَ الصَّادِقِينَ\"\nفقال لهم شعيب عليه السلام :\nخلااااص انتهى الأمر،\nكل واحد هيخليه زي ماهو بدماغه براحته خالص،\nوربنا عالم بأفعالكم ...إنتم كملوا إللي بتعملوه وإحنا هنكمل في إللي بنعمله وبكرة تشوفوا مين إللي هيجيله العذاب ومين هو الكذاب، استنوا وأنا مستني معاكم\n\"وَيَا قَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ سَوْفَ تَعْلَمُونَ مَنْ يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَاذِبٌ وَارْتَقِبُوا إِنِّي مَعَكُمْ إِنِّي مَعَكُمْ رَقِيبٌ\"\nودعا شعيب عليه السلام وقال:\n\"رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنْتَ خَيْرُ الْفَاتِحِينَ \"\nبعد فترة أصاب قوم مدين حر شديد جدا وسكنت الريح مفيش أي نسمة هوا لمدة سبعة أيام ومكنش بينفعهم ظل ولا ماء فخرجوا من البيوت للصحراء لعل وعسى يلاقوا طريقة للنجاة من الكرب ده،\nفربنا أرسل عليهم سحابة فاجتمعوا تحتها عشان تظللهم من حر الشمس،\nوأتاريها الظُّلة إللي فيها هلاكهم النهائي والعياذ بالله\n\"فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ\"\nفربنا زلزل الأرض من تحتهم زلزال شديد وأرسل عليهم الصيحة.\n \"وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ * كَأَنْ لَمْ يَغْنَوْا فِيهَا أَلَا بُعْدًا لِمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ\"\nوأمطر عليهم من السحابة الشرر والشهب، وماتوا جميعا موتة بشعة، ووشهم مدفوس في التراب في مشهد كله ذُل وصَغار وإهانة وتعذيب لهم\nونجّى الله شعيبا ومن آمن معه...\n\"وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا \"\nورجع شعيب عليه السلام ،\nعشان يشوف إللي حصل لقومه، فقالهم وهو بيعاتبهم:\nأنا بلغتكم رسالة ربنا ونصحتكم بس إنتم إللي مسمعتوش الكلام فإزاي أزعل على إللي حصل لناس كافرين زيكم، جحدوا نعمة ورحمة ربهم ورفضوها ؟!!\n\"فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَاتِ رَبِّي وَنَصَحْتُ لَكُمْ فَكَيْفَ آسَى عَلَى قَوْمٍ كَافِرِينَ\"\n《وهم كانوا سامعينه على فكرة\n ربنا بيخليهم يسمعوا زيادة في الألم والحسرة والعذاب》\nعرفتم مين الكذاب ...عرفتم مين الخسران...\nعرفتم مين إللي كان على حق ومين إللي كان على باطل؟\nبس خلاص ندمتم في وقت مينفعش فيه الندم.\n\"الَّذِينَ كَذَّبُوا شُعَيْبًا كَأَنْ لَمْ يَغْنَوْا فِيهَا الَّذِينَ كَذَّبُوا شُعَيْبًا كَانُوا هُمُ الْخَاسِرِينَ\"\n☆ربنا بيذكر لنا قصص الأنبياء عشان نعتبر ومنقعش في أخطاء أقوامهم...\nلما حد ينصحك خد نصيحته إنها رسالة ربنا باعتهالك، \nواحكم عليها بتجرد بدون اتباع هوى: هل النصيحة دي حق ولّا باطل؟ \nهل هتنفعني في صحيفتي لو نفذتها ولّا بالعكس ولّا مالهاش لازمة أصلا؟\nهو أه مفيش رُسل بعد رسول الله ﷺ لكن الرسالة نفسها موجودة  إللي هي آيات القرآن والأحاديث،\nأي آية أو حديث أو خُلق نبوي أو هَدْي من هدي السلف الصالح يوصلك فدي رسالة من ربنا والشخص إللي بيبلغك ده كأنه رسول حامل لرسالة ربنا ليك عشان يُرشدك للخير وصلاح أمرك قبل ما يسألك يوم القيامة لما النصيحة جت لك عملت إيه، هل اتبعتها ولاّ تكبرت وأعرضت عنها؟!\nفكده النصيحة أقامت الحجة عليك يوم القيامة\nزي ما بتقرأ كلامي دلوقتي...كلامي ده هيكون حجة ليك لو عملت بيه أو عليك يوم القيامة لو معملتش بيه،\nلو أطعت آيات ربنا وأحاديث رسوله فانت كده تشبهت بالذين آمنوا مع الأنبياء ...\nلو لا سمح الله قعدت تجادل بالباطل وتقول ده تشدد ...وأنا مش مقتنع ....والدين يُسر...وبطلوا فتْي... وخدت أسلوب إللي بينصحك عذر إنك متتبعش الحق ،وقعدت تدور على زلاّت العلماء إللي بيقولوا الكلام إللي على هواك وهو مخالف للدليل من القرآن والسنة؛\nفانت كده للأسف بتتشبه بالناس إللي خالفت الأنبياء، \nفحتى لو مش قادر تنفذ أوامر ربنا دلوقتي متجادلش بالباطل ومتردش الحق لمجرد إنك مش مستوعبه أو إنك مش مقتنع أو مش عاجبك الشخص إللي بيقوله،\nلو انت متأكد إنه حق لكن دماغك مش قادرة دلوقتي تقتنع بيه بشكل كامل اتعلم أكتر وابحث أكتر وادعي ربنا ينور بصيرتك ويرشدك\nالموضوع مش هزار والله... ده يا إما جنة أو نار...لما شوية زيت ولا شوية مية مغلية يطرطشوا على إيدنا بنبقى مش قادرين نستحمل فما بالنا باللي هيشرب الماء المغلي ده\nربنا ينجينا من النار برحمته ويرزقنا الجنة يارب ويوفقنا لكل ما يحب ويرضى\n¤آخر نقطة \n \nوهي إن أهل مدين دول غير أهل مدين إللي موسى عليه السلام هيروح لهم بعدين،\nوشعيب عليه السلام مش هو أبو المرأة إللي موسى هيتزوجها،\nأولا: لأن  القرآن والسنة لم يذكروا أي حاجة عن الموضوع ده.\nثانيا : المؤمنين من قوم شعيب مش هيسيبوا بنات نبيهم هم إللي يروحوا يسقوا الغنم.\nثالثا:\nالفرق الزمني بين موسى عليه السلام وشعيب عليه السلام كبير جدا ...بينهم مئات السنين.\nفالشيخ الكبير أبو البنتين هو رجل صالح من أهل مدين، وليس شعيب عليه السلام \nإن شاء الله المرة الجاية نتكلم عن إسحاق ويعقوب وبدايات قصة يوسف عليهم جميعا السلام\n#قصص_الأنبياء\n#الحلقة_التاسعة_عشرة\n#قصة_إسحاق_يعقوب_يوسف(١)\n#الرؤيا_والمَكِيدة\nقلنا قبل كده إن إبراهيم عليه السلام ربنا بشّره بابنه إسحاق على لسان الملائكة لما كانوا رايحين يُهلكوا قوم لوط،\nفإسحاق هو الابن الثاني لإبراهيم عليه السلام\nاتولد بعد إسماعيل عليه السلام بحوالي ١٣ سنة،\n\"وَبَشَّرْنَاهُ بِإِسْحَاقَ نَبِيًّا مِنَ الصَّالِحِينَ \"\nمفيش كلام كتير عنه في القرآن والسنة، هو كان نبي على نفس شريعة إبراهيم عليه السلام، \nوكان عنده ولدين: يعقوب والعِيص، والإتنين كانوا بارّين بأبوهم،\nزوجة إسحاق عليه السلام قالت لابنها يعقوب إنه يروح عند خاله واسمه \"لَابان\"\nويقعد عنده في مدينة حَرّان وهي موجودة حاليا في شرق تركيا،\nمسافة السفر كانت طويلة فكان بينام في الليل في الطريق، \nفنام على صخرة وشاف رؤيا ،\nشاف إن ربنا بيكلمه وبيقوله إنه هيُكَثَّرُ له في ذريته،\nيعني ذريته هتبقى كتيرة وربنا هيبارك له فيها وهتكون الأرض دي له هو وذريته،\nاستيقظ يعقوب عليه السلام من النوم وحط علامة على الحجر إللي كان نايم عليه عشان يعرف الأرض إللي ربنا قاله إنها هتكون له هو وذريته وسمى المكان ده \"بيت إِيل\"،\nوكلمة إِيل في لغتهم معناها الله...\nو\"بيت إِيل\" يعني بيت الله،\n فقال إنه هيبني في المكان ده بيت لربنا،\nوإسرا معناها عبد وإسرائيل معناها عبد الله، ده في لغتهم هم\nلكن احنا ماينفعش نسمي ربنا في شريعتنا الإسلامية العربية بإيل لأن أسماء الله في شريعتنا الخاتمة توقيفية،\n يعني ربنا عز وجل هو إللي يقولنا عليها، زي الرحمن والرحيم والعزيز و....و...فمينفعش احنا نخترع اسم ونسمي ربنا بيه \n \nالمهم،\nيعقوب عليه السلام كمّل طريقه ووصل عند خاله واستقر عنده مدة طويلة،\nطلب من خاله إنه يتزوج بنته واسمها \"راحِيل\"\nفقاله موافق بس بشرط إنك تشتغل عندي سبع سنين، \nفقاله ماشي وبعد السبع سنين زوّجه بنته الكبيرة \"لِيَا\"\nفقاله يا خالي أنا عايز راحيل مش لِيا فقاله عندنا ماينفعش الصغيرة تتزوج قبل الكبيرة،\nفقاله بس أنا عايز راحيل\nقاله مفيش مشكلة اشتغل عندي سبع سنين تانية وأزوجك راحيل\nففعلا اشتغل عنده سبع سنين تانية وبعدين تزوج من راحيل.\n¤كان في شريعتهم عادي إن الرجل يجمع في الزواج بين أختين.\nوقعد عند خاله ست سنين كمان لحد ما أتم عنده عشرين سنة،\nوكان بيرعى الغنم وربنا فتح عليه في الرزق وبقى عنده أموال كثيرة،\nربنا رزقه بستة أبناء من لِيا، \nوراحيل مخلفتش، \nفلما يئست إنها مش هتخلف أهدت يعقوب عليه السلام جارية لها عشان يتزوجها فالجارية دي خلّفت ليعقوب عليه السلام ولدين،\nتسكت \"لِيا\" \nلأ طبعا\nراحت هي كمان أهدت يعقوب عليه السلام جارية عشان يتزوجها فخلفت هي كمان ولدين،\n☆زمانكم مستغربين إيه الناس دي\nهو عادي كده الواحدة تدي لزوجها امرأة تانية \nطبعا الزمن والتربية بيختلف، يعني احنا أجيال اتربينا على رفض الزوجة التانيةنفسيا -مش شرعا طبعا وإلا يبقى كفر والعياذ بالله- \nواتربينا على إنها خطافة الرجالة ونظرة الناس لده فيها حرج وشماتة و...و...،بعكس الأزمنة إللي فاتت،\nوكمان إنتشار الجواري في الأزمنة إللي فاتت كان مخلي الأمور طبيعية أكتر من كده، فأكيد طبعا لازم نستغرب من النساء بتوع زمان\nفيعقوب عليه السلام اتولد له دلوقتي عشر أبناء...\nلكن راحيل مخلفتش، فيُذكر إنه دعا الله أن يرزقه ولد من راحيل وهي كمان دعت، فربنا رزقها بيوسف وبينيامين،\nبعد ما أتم يعقوب عليه السلام عشرين سنة عند خاله قرر إنه يرجع عند أبوه إسحاق وأمه وأخاه، فرجع فعلا لأهله واستقر معاهم،\nرجع يعقوب عليه السلام للمكان إللي حط عنده العلامة وبنى هناك بيت المقدس، وكان ثاني بيت لله في الأرض،\nالبيت الأول كان الكعبة والتاني هو بيت المقدس،\nورجع قعد مع أبيه إسحاق ومات إسحاق عليه السلام بعد مدة وقيل إنه مات وهو عنده ١٨٠ سنة،\n☆طبعا الأسماء والأحداث\n التفصيلية دي من الإسرائيليات التي لا نصدقها ولا نكذبها واحنا كنا اتكلمنا في أنواع الإسرائيليات قبل كده والمقبول منها والمرفوض منها لو تفتكروا،\nوأهل التفسير ذكروا التفاصيل دي عشان نفهم السياق المبدئِي والتخيلي للقصة ماشي إزاي \nيعقوب عليه السلام اتولد له ١٢ ولد، واختلف أهل العلم هل أبناؤه دول هم الأسباط ولّا لأ\nوالأسباط معناها ذرية الإنسان \nسواء أبناؤه مباشرة أو أحفاده أو أحفاد أحفاده المهم إنهم من ذرية الإنسان،\n\" قُلْ آمَنَّا بِاللَّهِ وَمَا أُنزِلَ عَلَيْنَا وَمَا أُنزِلَ عَلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ ،\nوَمَا أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَالنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ\"\nوالصحيح إن أبناء يعقوب عليه السلام مش الأسباط لأن الأسباط كانوا كلهم أنبياء،\nوأفعال أبناء يعقوب عليه السلام مع أخوهم يوسف زي ما هنشوف مش أخلاق أنبياء حتى قبل الرسالة\nفي يوم من الأيام جه ليعقوب عليه السلام ابنه الصغير يوسف بيحكيله عن حاجة حصلت معاه،\nوهي إنه شاف رؤيا....شاف الشمس والقمر و١١ كوكب بيسجدوا له\nقال له يعقوب عليه السلام يابني خلّي الموضوع في سرّك ومتحكيش لإخواتك أي حاجة\n\"قَالَ يَا بُنَيَّ لَا تَقْصُصْ رُؤْيَاكَ عَلَىٰ إِخْوَتِكَ \"\n☆إيه ده ليه\nيوسف عليه السلام الكريم بن الكريم بن الكريم بن الكريم،\nربنا وهبه نصف جمال البشر،\nيعني ربنا لما خلق جمال البشر قسمه نصفين، قسم اتوزع على البشر من ذرية آدم حتى نهاية الدنيا والنص التاني ربنا أعطاه ليوسف\nفمهما شوفنا حد شكله جميل فهو ميجيش ذرة في جمال يوسف عليه السلام\nفلما يكون طفل بالجمال ده طبيعي إن الناس تنجذب ليه ويهتموا بيه وخصوصا أبوه وأمه،\nويا سلام لو جمع مع الجمال الخارجي ده جمال داخلي من حُسن خلق وصفاء قلب، ويا سلام لو زوّد لده كله بشارة بالنبوة\nمتخيلين الحسد إللي ممكن يتعرض له من إللي حواليه\nده بعض النساء بيبقى ربنا رازقها بشوية جمال ولّا شوية طاعات وتبقى حاسة إنها محسودة من إللي حواليها، فما بالنا بواحد زي يوسف عليه السلام\n☆وطبعا هنا حد ممكن يسأل:\nهل معنى كده إن سيدنا يوسف عليه السلام أحلى من النبي محمد ﷺ\nبصفة عامة رسول الله ﷺ هو أفضل البشر على الإطلاق وكان من أجمل الناس وأحسنهم،\nأما من ناحية المقارنة بين رسول الله ﷺ وبين يوسف عليه السلام من ناحية الشكل مين الأجمل فيهم فالعلماء اختلفوا:\n◇فريق قال:\n إن يوسف عليه السلام ربنا فضّله بالجمال على كل البشر حتى رسول الله ﷺ وأعطاه نصف جمال البشر،\nلحديث رسول الله ﷺ لما كان في رحلة المعراج:\n\" فَإِذَا أَنَا بِيُوسُفَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، إِذَا هُوَ قَد اُعْطِيَ شَطْرَ الْحُسْنِ\"\n◇فريق ثاني من العلماء قال:\nإن يوسف عليه السلام كان أجمل من كل البشر ما عدا رسول الله ﷺ، واستدلوا بنفس الحديث إللي قلناه\n وقالوا  إن المُتكلم إللي هو رسول الله ﷺ  لا يدخل في عمومِ خطابه، يعني رسول الله ﷺ ميدخلش في الكلام،\nوإن رسول الله ﷺ أُعطي كل الجمال ويوسف أُعطي نصفه\nومش معنى يا جماعة إن رسول الله ﷺ يكون أقل جمالا من يوسف عليه السلام إن ده نقص في حقه ﷺ، بالعكس ده لعل كده أكمل في حقه ﷺ \nليه\nلأن الأكمل في الرجال إنه ميكنش شديد الجمال بالطريقة دي، ولأن رسول الله ﷺ هو أكمل البشر فكان من الطبيعي إنه يكون جماله أقل من يوسف عليه السلام، \nيعني تخيلوا إن يوسف عليه السلام الناس كانت بتنبهر بجماله وهو أُوتي نصف الجمال،\nفتخيلوا لو رسول الله ﷺ كان له الجمال كله أو أكثر جمالا من يوسف عليه السلام \nكانت الناس هتنشغل بجماله ﷺ عن الرسالة إللي هو جاي بيها، لأن طبيعة البشر إنهم بينجذبوا للشيء الجميل، فممكن الواحد يرضى بكلام هو مش مقتنع بيه عشان إللي قاله شكله حلو،\nأو يتغاضى عن أخطاء إللي قصاده بسبب جماله وشكله\nولعل ده كمان من حكمة ربنا إنه جعل كل الأنبياء شكلهم حلو وصوتهم حلو، \nعشان لما يدعوا قومهم يتقبلوا كلامهم، بعكس لو حد شكله قبيح أو شكله عادي محدش هينجذب له\nده غير إن جماله الزائد ﷺ هيتسبب في فتنة شديدة بين الناس، وخصوصا إن رسول الله ﷺ مكنش قاعد في مكان واحد زي يوسف عليه السلام، ده بيروح هنا وهنا وبيقابل ده وبيقابل، حتى النساء كانوا بيسألوه عن أمور الدين،\nواحنا هنشوف لما نساء عِلية القوم شافوا يوسف إزاي قطعوا أيديهن ومكنوش حاسين بالألم\nلكن ده محصلش مع رسول الله ﷺ في أي موقف من مواقف \nحياته \nالمهم،\nيعقوب عليه السلام  قال ليوسف متحكيش لإخواتك على الرؤيا دي عشان محدش فيهم يؤذيك، إنت عارف الشيطان وعمايله\n\"فَيَكِيدُوا لَكَ كَيْدًا ۖ إِنَّ الشَّيْطَانَ لِلْإِنسَانِ عَدُوٌّ مُّبِينٌ.\"\nوزي ما انت شفت كده من الرؤيا دي يا يوسف، ربنا هيختارك ويعلمك تعبير الرؤى وتفسيرها –وده علم عظيم جدا ومدهش- وهيتم نعمته عليك بإنك هتكون نبي في المستقبل زي آبائك إبراهيم وإسحاق،\n\"وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ الْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ وَعَلَىٰ آلِ يَعْقُوبَ كَمَا أَتَمَّهَا عَلَىٰ أَبَوَيْكَ مِن قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ.\"\nفي الوقت ده إخوة يوسف مجتمعين مع بعض وبيتحاوروا،\nيا جماعة إنتم شايفين أبونا بيحب يوسف وأخوه أكتر مننا إزاي مع إننا جماعة واحنا الأكتر والأنفع له بعددنا ويوسف لوحده\nأبونا غلطان جدا في إللي بيعمله ده\n\" إِذْ قَالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِي ضَلَالٍ مُّبِينٍ \"\n¤السؤال بقى، هل يعقوب عليه السلام كان بيحب يوسف أكتر من إخواته زي ما هم قالوا ؟!\nشوفوا،\nهو أه يوسف عليه السلام يتحب وكان ظاهر عليه علامات النباهة والذكاء وإنه هيكون له شأن وكمان شكله الجميل، والطبيعي إن الإنسان يحب كل حاجة شكلها جميل،\nلكن مش معنى كده إن يعقوب عليه السلام كان بيحب يوسف اكثر منهم\nمفيش أي دليل على كده، وحتى يعني لو هو فعلا كان بيحب يوسف أكثر، فمش معنى كده إنه كان بيفرق بينهم في المعاملة\nيعقوب عليه السلام نبي ومُربّي فهو عارف كويس إنه لازم يعدل بين أبناؤه، وخدوا بالكم إن في فرق بين العدل والمساواة،\nالعدل إني أعطي لكل واحد من عيالي إللي هو محتاج له من الحب والاهتمام على حسب سنه، لكن المساواة إني أعطيهم كلهم زي بعض بالضبط من غير ما أراعي فرق السن أو الاحتياجات، وكده هيبقى ظلم \nهقول لكم مثال للتوضيح\nعارفين الطفل لما بيكون لسه مولود بيحتاج رعاية جامدة جدا بعكس الطفل إللي عنده سبع سنين مثلا،\nفالعدل بقى إن الطفل إللي لسه مولود ده أرضعه وأشربه وأغير له هدومه وأغيرله بامبرز وأشيله وألاعبه وأسهر بيه بالليل، وباقي الحاجات إللي انتم عارفينها دي\nهل العدل بقى إني أعمل نفس الحاجات دي مع الطفل إللي عنده سبع سنين\nيعني أغير له بامبرز وأشيله وألاعبه وأأكله وأشربه زيه زي أخوه إللي عنده شهرين مثلا\nطبعا لأ، أنا لو عملت كده يبقى أنا بساوي بينهم وده كده بقى ظلم للكبير، لييييه\nلأن الكبير احتياجاته مختلفة خالص، أكله مختلف وعقليته مختلفة،\nأيوة أنا هوفر له الأكل المناسب له وهوفر له اللعب المناسب له، لكن مش هينفع أشيله زي ما بشيل الصغير\nفالعدل وإللي ربنا هيحاسبني عليه هو إني أوفر لكل واحد من عيالي احتياجاته سواء النفسية أو الاحتياجات اليومية\nوهو ده بالضبط إللي يعقوب عليه السلام كان عارفه وفاهمه وبيطبقه،\nفطبيعي إن الصغير هياخد وقت أكبر، زي ما إخواته لما كانوا صغيرين وفي نفس سنه أخدوا نفس الوقت بالضبط، \nيعني مثلا لما يكون عندنا طفل عنده أربع سنين لسه بيتعلم الحروف، مش الطبيعي إننا بناخد معاه وقت أكبر لتعليمه، بعكس أخوه إللي عنده عشر سنين مثلا هو ممكن يعتمد على نفسه وأنا أكون مجرد عامل مساعد\nطبعا دلوقتي أنا بتكلم من ناحيتنا احنا كأباء وأمهات،\nلكن الناحية التانية بقى وهي وجهة نظر الأبناء مش بتكون زي ماحنا شايفينها،\nاحنا فاكرين كل حاجة عملناها مع ولادنا لكن أبناءنا لأ، ميفتكروش إننا عملنا معاهم إللي عملناه مع أخوهم الصغير ده، فيبدأوا بقى يترجموا اهتمامنا بالصغير إننا بنحبه أكثر منهم،\nمع إن الطبيعي أصلا إن الطفل الصغير المفروض يبقى مُحاط بالحب والرعاية والاهتمام،\nلكن للأسف ساعات مهما حاولنا نفهّم ونشرح، إللي في دماغهم في دماغهم،\nوهو ده بالضبط إللي كان فيه إخوة يوسف\nترجموا اهتمام يعقوب عليه السلام كأب بطفلين صغيرين محتاجين رعاية إنه كده بيحبهم أكتر منهم\nويعقوب عليه السلام كان حاسس بغيرتهم من يوسف عليه السلام، لكن مكنش بإيده يعمل حاجة للغيرة دي،\nلأن واضح إن الغيرة والحسد عمُوا قلوبهم لدرجة إنهم مش قادرين يفرقوا بين مصلحة الصغير ومصلحة الكبير\nفالشاهد من الكلام كله إن يعقوب عليه السلام مكنش بيفرق في المعاملة بين أبناؤه،\nلكن أبناؤه الكبار هم إللي ترجموا تصرفات يعقوب عليه السلام الصحيحة تجاه يوسف وبنيامين غلط، وبدأوا يحاسبوه على ظنهم هم،\nومكلفوش نفسهم حتى يرُوحوا يسألوه ويتأكدوا من ظنهم وعلى طول اتهموه إنه في ضلال مبين، وده طبعا سوء أدب مع أبوهم، وكمان مش أي أب ده نبي من الأنبياء\nوطبعا بعد ما فهمنا نفسية إخوة يوسف خلونا نشوف الحل إللي وصلوا له عشان يعالجوا المشكلة دي\nقالوا:\nاقتلوا يوسف ونخلص من القصة دي كلها وساعتها مش هيكون قصاد أبونا حل غير إنه يحبنا إحنا بداله\nوبعدها هنتوب إن شاء الله وخلاص والتوبة بتمسح إللي قبلها\n\" اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِن بَعْدِهِ قَوْمًا صَالِحِينَ\"\n☆طيب ويوسف ذنبه إيه هنا اصلا\n أبوه هو إللي بيحبه، يعني لو في خطأ فهيكون الخطأ من أبوه..\nيعني العدل ساعتها إن الأب هو إللي يُقتل مش يوسف\nلكن بسبب الحسد ورغبتهم في الاستئثار بوجه أبيهم تماما لأنفسهم، تفكيرهم كان في قتل يوسف\nثم مين إللي إداهم الضمان إن ربنا هيقبل توبتهم ولا فين الضمان إنهم هيعيشوا لحد ما يتوبوا أصلا\nمش يمكن ربنا يختم لهم على معصية القتل دي ويبقى خسروا الدنيا والآخرة،\nثم إيه الحل الدموي ده\n \nمجاش في بالهم مثلا إنهم يقعدوا يتكلموا مع أبوهم ويطلبوا منه إنه ياخد باله منهم ويهتم بيهم هم كمان وإنهم بيغيروا منه\nلكن الغيرة فرضت نفسها والشيطان مصدق وزودها في قلوبهم لحد ما وصلها للحسد،\nوبطبيعة البشر، الكبير بيغير من الصغير لأن الأبوين بيدوله إهتمام أكبر من الكبير، وده بسبب طبيعة سنه الصغير وضعفه واحتياجه وقلة خبرته زي ما قلنا،\nولو تفتكروا: قابيل قتل هابيل بسبب الغيرة إللي اتحولت للحسد\nالغيرة أمر طبيعي ربنا فطره جوانا عشان نسعى للتنافس الشريف في الخير والطاعات يعني نغِير من بعض في التنافس بشكل عام على الآخرة، \nلكن تحوُّلها للحسد بسبب غيرتنا من بعض على الدنيا هو إللي مذموم ومش طبيعي،\nلو اتحكمنا فيها وقاومناها يبقى احنا لحقنا نفسنا،\nلكن لو سيبناها في قلوبنا تزيد هتتحول لحسد وتخلي الإنسان يقع في المحرم، عشان كده الحسد بياكل الحسنات زي ما النار بتاكل الحطب\nالمهم..\nواحد من إخوة يوسف قال يا جماعة بلاش تقتلوا يوسف مهما كان ده أخوكم، \nانتم مش عايزينه يكون موجود فقط، صح؟\nخلاص ارموه في بئر من الآبار، والناس وهي معدية تاخد مية من البئر هتلاقيه وتاخده معاها وتبقوا خلصتوا منه من غير قتل ولا حاجة،\n\" قَالَ قَائِلٌ مِّنْهُمْ لَا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيَابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِن كُنتُمْ فَاعِلِينَ\"\nفاتفقوا فعلا إنهم يرموه في البئر بدل ما يقتلوه،\nوراحوا لأبوهم وقالو له إنهم عايزين ياخدوا يوسف معاهم وهم خارجين عشان يلعب ويستمتع \nفأبوهم قالهم أنا بحزن لما يوسف بيبعد عني \n \nوقالهم إنه خايف أحسن الذئب ياكله وهم مش واخدين بالهم،\n\" قَالَ إِنِّي لَيَحْزُنُنِي أَن تَذْهَبُوا بِهِ وَأَخَافُ أَن يَأْكُلَهُ الذِّئْبُ وَأَنتُمْ عَنْهُ غَافِلُونَ\"\n☆وممكن الكلمة دي تكون زوّدت الغيرة في قلوبهم كمان\nيعني عادي بالنسبة لك إننا منكنش موجودين لكن يوسف لأ مش عادي يغيب عن عينك\nمع إنهم لو فكروا شوية هيلاقوا إن حزنه بيكون بسبب قلقه عليه طول غيابه بسبب ضعفه زي ما قلنا، ولعل بسبب علمه إنهم بيعاملوه بقسوة أحيانا بسبب الغيرة، بدليل إنهم قالوا: مالك لا تأمننا على يوسف؟\nيعني واضح إنه من زمان واخد القرار ده،لأنه عارف إن وجوده معاهم مش أمان، وهمّ عارفين ده بوضوح\nفردوا عليه وقالوا إزاي الذئب ياكله واحنا مجموعة كبيرة كده، ده لو حصل يبقى احنا عاجزين وفشلة ما لناش لازمة \n\" قَالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذًا لَّخَاسِرُونَ\"\nفي النهاية.. يعقوب عليه السلام وافق إن يوسف يروح مع إخواته....\nيا ترى هل إخوة يوسف هيرموه في البئر ولا هيشفقوا على أخوهم الصغير ويغيروا رأيهم؟\nهنعرف الإجابة في الجزء الجاي إن شاء الله"}]);
